// Pure builders and parsers for the two note kinds Discover writes. No filesystem
// access: every function here is a string transform so the note format can be
// tested and reasoned about without a vault.

export const CHAT_DIR = 'Chats';
export const SOURCE_DIR = 'Sources';
export const DISCOVER_DIR = '_discover';
export const VOICE_PATH = 'Style/Voice.md';

/** Marker pairs for the blocks Discover rewrites in place. */
export const MARKERS = Object.freeze({
  related: Object.freeze({ start: '<!-- discover:related:start -->', end: '<!-- discover:related:end -->' }),
  refs: Object.freeze({ start: '<!-- discover:refs:start -->', end: '<!-- discover:refs:end -->' }),
});

const CHAT_KEYS = ['discover', 'chat', 'title', 'created', 'updated', 'topics', 'tags', 'sources', 'model'];
const SOURCE_KEYS = ['discover', 'title', 'url', 'kind', 'retrieved', 'hash'];
const KEY_ORDER = new Map([...CHAT_KEYS, ...SOURCE_KEYS].map((key, index) => [key, index]));
const FENCE = /^\s*(`{3,}|~{3,})/;

function blank(value) {
  return value === null || value === undefined;
}

function scalar(value) {
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return `[${value.map(scalar).join(', ')}]`;
  return JSON.stringify(String(value));
}

function orderedKeys(keys) {
  return [...keys].sort((a, b) => {
    const left = KEY_ORDER.has(a) ? KEY_ORDER.get(a) : Number.MAX_SAFE_INTEGER;
    const right = KEY_ORDER.has(b) ? KEY_ORDER.get(b) : Number.MAX_SAFE_INTEGER;
    return left === right ? a.localeCompare(b) : left - right;
  });
}

/** A YAML frontmatter block, keys in the order Obsidian property panes read best. */
export function frontmatter(fields) {
  const keys = orderedKeys(Object.keys(fields || {}).filter(key => !blank(fields[key])));
  if (!keys.length) return '';
  const lines = keys.map(key => `${key}: ${scalar(fields[key])}`);
  return `---\n${lines.join('\n')}\n---\n\n`;
}

/** Split a note into its frontmatter fields and the body that follows. */
export function parseFrontmatter(text) {
  const value = String(text ?? '');
  const match = /^---\r?\n([\s\S]*?)\r?\n---[ \t]*\r?\n?/.exec(value);
  if (!match) return { data: {}, body: value };
  const data = {};
  for (const line of match[1].split(/\r?\n/)) {
    const pair = /^([A-Za-z0-9_-]+):[ \t]*(.*)$/.exec(line);
    if (!pair) continue;
    const raw = pair[2].trim();
    if (!raw) { data[pair[1]] = ''; continue; }
    try { data[pair[1]] = JSON.parse(raw); }
    catch { data[pair[1]] = raw; }
  }
  return { data, body: value.slice(match[0].length) };
}

/** An Obsidian callout. `collapsed` uses the `-` marker; blank lines become `>`. */
export function callout(kind, title, body = '', { collapsed = true } = {}) {
  const marker = `> [!${kind}]${collapsed ? '-' : ''}${title ? ` ${title}` : ''}`;
  const lines = String(body ?? '').split(/\r?\n/).map(line => (line.trim() ? `> ${line}` : '>'));
  return [marker, ...lines].join('\n');
}

/** `## 3. <question>` — the question is reproduced verbatim on one line. */
export function questionHeading(index, question) {
  const text = String(question ?? '').replace(/\s+/g, ' ').trim();
  return `## ${index}. ${text}`;
}

export function formatTimestamp(value = new Date()) {
  const date = value instanceof Date ? value : new Date(value);
  if (!Number.isFinite(date.getTime())) throw new Error('Invalid timestamp');
  const pad = number => String(number).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

export function dateStamp(value = new Date()) {
  const date = value instanceof Date ? value : new Date(value);
  if (!Number.isFinite(date.getTime())) throw new Error('Invalid date');
  const pad = number => String(number).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

const FORBIDDEN = /[\\/:*?"<>|#^[\]]/g;

/** A filename-safe title. Empty input still yields a usable name. */
export function sanitizeTitle(text) {
  const cleaned = String(text ?? '')
    .replace(FORBIDDEN, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/[. ]+$/, '')
    .slice(0, 80)
    .trim();
  return cleaned || 'Untitled chat';
}

export const sourceTitle = title => sanitizeTitle(title);
export const sourceFileName = (title, hash8) => `${sanitizeTitle(title)} (${hash8}).md`;
export const chatFileName = (date, title) => `${CHAT_DIR}/${dateStamp(date)} ${sanitizeTitle(title)}.md`;
export const sourcePath = (title, hash8) => `${SOURCE_DIR}/${sourceFileName(title, hash8)}`;

/** The exact wiki-link string the writer is given and must reproduce. */
export function sourceRef(sourceId, title, hash8) {
  const name = sanitizeTitle(title);
  const stamp = hash8 || String(sourceId ?? '').slice(0, 8);
  return `[[${SOURCE_DIR}/${name} (${stamp})|${name}]]`;
}

/** The `Sources/<Title> (<hash8>)` target of a wiki-link, ignoring display text. */
export function wikilinkTarget(ref) {
  return String(ref ?? '').replace(/^\[\[/, '').replace(/\]\]$/, '').split('|')[0].split('#')[0].trim();
}

export function relatedBlock(entries = []) {
  const lines = entries
    .filter(entry => entry?.path)
    .map(entry => `> - [[${String(entry.path).replace(/\.md$/, '')}]]${entry.reason ? ` — ${entry.reason}` : ''}`);
  if (!lines.length) return '';
  return [MARKERS.related.start, callout('link', 'Related', lines.map(line => line.slice(2)).join('\n')), MARKERS.related.end].join('\n');
}

/** Insert a chunk immediately before a marker block, or at the end when absent. */
function spliceBefore(text, markerStart, chunk) {
  const value = String(text ?? '');
  const at = markerStart ? value.indexOf(markerStart) : -1;
  if (at === -1) return `${value.trimEnd()}\n\n${chunk}`;
  const head = value.slice(0, at).trimEnd();
  return `${head}\n\n${chunk}\n${value.slice(at)}`;
}

/**
 * Append one exchange to a chat note. Existing content is untouched: the new
 * section lands above the related block (or at the end when there is none).
 * `{index, question, provenance, body}` — provenance and body are ready Markdown.
 */
export function appendExchange(noteText, { index, question, provenance, body }) {
  const parts = [questionHeading(index, question)];
  if (provenance) parts.push(provenance);
  parts.push(String(body ?? '').trim());
  const chunk = `${parts.join('\n\n')}\n`;
  return spliceBefore(noteText, MARKERS.related.start, chunk);
}

/** Replace a marker-delimited block. An empty block removes it and its gap. */
export function rewriteBlock(noteText, marker, block) {
  const { start, end } = MARKERS[marker] || {};
  if (!start) throw new Error(`Unknown note block: ${marker}`);
  const value = String(noteText ?? '');
  const from = value.indexOf(start);
  if (from === -1) return block ? spliceBefore(value, null, `${block}\n`) : value;
  const to = value.indexOf(end, from);
  const tail = to === -1 ? '' : value.slice(to + end.length);
  const head = value.slice(0, from).trimEnd();
  const next = block ? `${head}\n\n${block}\n` : `${head}\n`;
  return `${next}${tail.replace(/^\s*\n?/, '')}`;
}

/** Split a chat note into `## <question>` exchanges. Fenced code is ignored. */
export function splitExchanges(noteText) {
  const lines = String(noteText ?? '').split(/\r?\n/);
  const exchanges = [];
  let fence = null;
  let current = null;
  let buffer = [];
  const flush = () => {
    if (!current) return;
    const body = buffer.join('\n').split(MARKERS.related.start)[0].trim();
    exchanges.push({ question: current, body });
  };
  for (const line of lines) {
    const fenceMatch = FENCE.exec(line);
    if (fenceMatch) {
      if (fence && line.trim().startsWith(fence)) fence = null;
      else if (!fence) fence = fenceMatch[1];
    }
    if (!fence && /^##\s+\d+\.\s+/.test(line)) {
      flush();
      current = line.replace(/^##\s+\d+\.\s+/, '').trim();
      buffer = [];
      continue;
    }
    if (!fence && /^##\s+/.test(line)) {
      flush();
      current = line.replace(/^##\s+/, '').trim();
      buffer = [];
      continue;
    }
    if (current) buffer.push(line);
  }
  flush();
  return exchanges;
}

/** The tail of the conversation, for the writer's context. */
export function recentExchanges(noteText, count = 3, charBudget = 6000) {
  const exchanges = splitExchanges(noteText).slice(-Math.max(0, count));
  if (!exchanges.length) return '';
  const text = exchanges.map(({ question, body }) => `Q: ${question}\nA: ${body}`).join('\n\n');
  if (text.length <= charBudget) return text;
  const cut = text.slice(text.length - charBudget);
  const at = cut.indexOf('\n');
  return (at === -1 ? cut : cut.slice(at + 1)).trim();
}

/** Obsidian-safe Markdown: delimiters, blank runs and trailing whitespace. */
export function normalizeObsidianMarkdown(text) {
  const lines = String(text ?? '').split(/\r?\n/);
  const out = [];
  let fence = null;
  for (const line of lines) {
    const fenceMatch = FENCE.exec(line);
    if (fenceMatch) {
      if (fence && line.trim().startsWith(fence)) fence = null;
      else if (!fence) fence = fenceMatch[1];
    }
    const trimmed = line.replace(/[ \t]+$/, '');
    out.push(fence ? trimmed : trimmed
      .replace(/\\\(/g, '$').replace(/\\\)/g, '$')
      .replace(/\\\[/g, '$$').replace(/\\\]/g, '$$'));
  }
  const collapsed = [];
  let blanks = 0;
  for (const line of out) {
    if (!line) {
      blanks++;
      if (blanks <= 2 && collapsed.length) collapsed.push('');
      continue;
    }
    blanks = 0;
    collapsed.push(line);
  }
  return `${collapsed.join('\n').trimEnd()}\n`;
}

/** First free `<dir>/<base> [n]<ext>` path. `exists` may be async. */
export async function uniquePath(exists, dir, baseName, ext) {
  for (let index = 1; index <= 999; index++) {
    const name = index === 1 ? baseName : `${baseName} ${index}`;
    const candidate = `${dir}/${name}${ext}`;
    if (!(await exists(candidate))) return candidate;
  }
  throw new Error(`Too many files named ${baseName}${ext} in ${dir}.`);
}

/** First 700 characters of `text`, cut at a sentence boundary when there is one. */
export function briefFrom(text, limit = 700) {
  const value = String(text ?? '').trim();
  if (value.length <= limit) return value;
  const window = value.slice(0, limit);
  const stop = Math.max(window.lastIndexOf('. '), window.lastIndexOf('.\n'));
  return (stop >= 200 ? window.slice(0, stop + 1) : window.trimEnd());
}

