// The vault layer: path confinement, atomic writes, the single-writer lock, the
// chat/source note formats and everything derived from them. Nothing above this
// module touches the filesystem directly.
import * as fs from 'node:fs/promises';
import * as os from 'node:os';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import {
  CHAT_DIR, DISCOVER_DIR, MARKERS, SOURCE_DIR,
  chatFileName, frontmatter, normalizeObsidianMarkdown, parseFrontmatter, refsBlock,
  relatedBlock, rewriteBlock, sanitizeTitle, sourceFileName, sourceRef,
  uniquePath, dateStamp,
} from './notes.mjs';
import { createIndex } from './index-store.mjs';

const locks = new Map();
const ID = /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/;
const HASH = /^[0-9a-f]{64}$/;
