    if (!created) return null;
    return frontmatter({
      discover: 'chat', chat: record.id, title: record.title, created: record.createdAt,
      updated: record.updatedAt, topics: record.topics || [], tags: (record.topics || []).map(topic => `discover/${topic}`),
      sources: 0, model: record.model,
    }) + `# ${record.title}\n`;
  }

  /** The header block of a chat note, refreshed whenever the note changes. */
  static chatHeader(record, { sourceCount = 0 } = {}) {
    return frontmatter({
      discover: 'chat', chat: record.id, title: record.title, created: record.createdAt,
      updated: record.updatedAt, topics: record.topics || [], tags: (record.topics || []).map(topic => `discover/${topic}`),
      sources: sourceCount, model: record.model,
    }) + `# ${record.title}\n`;
  }

  static relatedBlock = relatedBlock;
  static dateStamp = dateStamp;
}

