  async findChatNote(chatId) {
…
  }

  async relatedChats(chatId, { limit = 3 } = {}) { return this.index.related(chatId, limit); }

  async getChat(id) { return this.index.getChat(id); }

  async getSource(id) { return this.index.getSource(id); }

  /** Newest first, with records whose note file disappeared dropped and reported. */
  async listChats() {
    const chats = await this.index.chats();
    const present = [];
    this.skippedChats = [];
    for (const chat of chats) {
      if (await this.exists(chat.path)) present.push(chat);
      else this.skippedChats.push(chat.title || chat.path);
    }
    return present;
  }

  async saveChat(record) { await this.index.saveChat(record); }

  async setActive(chatId) { await this.index.setActive(chatId); }

  async getActive() { return this.index.getActive(); }

  static buildChatNote(record, { created = false } = {}) {
    if (!created) return null;
    return frontmatter({
      discover: 'chat', chat: record.id, title: record.title, created: record.createdAt,
      updated: record.updatedAt, topics: record.topics || [], tags: (record.topics || []).map(topic => `discover/${topic}`),
      sources: 0, model: record.model,
    }) + `# ${record.title}\n`;
  }

  /** The header block of a chat note, refreshed whenever the note changes. */
  static chatHeader(record, { sourceCount = 0 } = {}) {
    return frontmatter({
      discover: 'chat', chat: record.id, title: record.title, created: record.createdAt,
      updated: record.updatedAt, topics: record.topics || [], tags: (record.topics || []).map(topic => `discover/${topic}`),
      sources: sourceCount, model: record.model,
    }) + `# ${record.title}\n`;
  }

  static relatedBlock = relatedBlock;
  static dateStamp = dateStamp;
