// One stateless model call, the way the host itself makes one: Pi's active
// registry supplies provider, credentials and headers, so custom providers and
// OAuth refresh keep working. No session, no transcript, nothing persisted.
import { randomUUID } from 'node:crypto';

let clampThinkingLevel = value => value;
try { ({ clampThinkingLevel } = await import('@earendil-works/pi-ai')); }
catch { /* Older host without the helper: pass the level through unchanged. */ }

const STALL = 'The model stopped producing output';

function stallError(ms) {
  return new Error(`${STALL} for ${Math.round(ms / 1000)}s.`);
}

/** Watch a stream so a dead connection fails the turn instead of hanging it. */
async function pacedStream(stream, { signal, stallMs, onEvent }) {
  let timer;
  let fail;
  const stalled = new Promise((_, reject) => { fail = reject; });
  const arm = () => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => fail(stallError(stallMs)), stallMs);
    timer.unref?.();
  };
  arm();
  const observe = async () => {
    if (typeof stream?.[Symbol.asyncIterator] !== 'function') return;
    const iterator = stream[Symbol.asyncIterator]();
    let reported = 0;
    while (!signal.aborted) {
      const next = await iterator.next();
      if (next.done) return;
      arm();
      const type = next.value?.type;
      if (onEvent && Date.now() - reported >= 1000) {
        reported = Date.now();
        if (type === 'thinking_delta') onEvent('thinking');
        else if (type === 'text_delta') onEvent('writing');
        else if (type === 'toolcall_delta') onEvent('tool');
      }
    }
  };
  try {
    const [response] = await Promise.all([Promise.race([stream.result(), stalled]), observe()]);
    return response;
  } finally {
    if (timer) clearTimeout(timer);
  }
}

function usable(response) {
  if (!response || response.role !== 'assistant' || !Array.isArray(response.content)) {
    throw new Error('The model returned an invalid response.');
  }
  return response;
}

/**
 * Bind the transport once per turn: the reasoning level, provider and request
 * identity stay fixed while the turn makes its handful of calls.
 */
export function createModelCaller({ registry, model, thinkingLevel }) {
  if (!registry || typeof registry.complete !== 'function') throw new Error('No model registry is available.');
  if (!model || typeof model.id !== 'string') throw new Error('No model is selected.');
  const level = thinkingLevel === undefined || thinkingLevel === null ? undefined : clampThinkingLevel(model, thinkingLevel);
  const provider = level && level !== 'off' && typeof registry.getProvider === 'function' ? registry.getProvider(model.provider) : null;
  const composed = Boolean(provider && typeof provider.streamSimple === 'function' && typeof registry.getApiKeyAndHeaders === 'function');

  return {
    model,
    composed,
    thinkingLevel: level,
    async call({ systemPrompt, messages, tools = [], signal, maxTokens, timeoutMs = 180_000, stallMs = 90_000, onEvent }) {
      const context = { systemPrompt, messages, tools };
      const controller = new AbortController();
      const cancel = () => controller.abort(signal?.reason ?? new Error('The turn was cancelled.'));
      if (signal) {
        if (signal.aborted) cancel();
        else signal.addEventListener('abort', cancel, { once: true });
      }
      const timer = setTimeout(() => controller.abort(new Error('The model call exceeded its time limit.')), timeoutMs);
      timer.unref?.();
      const options = {
        signal: controller.signal, maxTokens, maxRetries: 0, timeoutMs,
        sessionId: randomUUID(), transport: 'sse',
      };
      try {
        if (!composed) {
          return usable(await Promise.race([
            registry.complete(model, context, options),
            new Promise((_, reject) => {
              const guard = setTimeout(() => reject(stallError(stallMs)), stallMs);
              guard.unref?.();
            }),
          ]));
        }
        const auth = await registry.getApiKeyAndHeaders(model);
        if (!auth?.ok) throw new Error('The selected model could not be authenticated.');
        const requestModel = auth.baseUrl ? { ...model, baseUrl: auth.baseUrl } : model;
        const stream = provider.streamSimple(requestModel, context, {
          ...options, apiKey: auth.apiKey, headers: auth.headers, env: auth.env,
          reasoning: level === 'off' ? undefined : level,
        });
        return usable(await pacedStream(stream, { signal: controller.signal, stallMs, onEvent }));
      } catch (error) {
        controller.abort(error);
        throw error;
      } finally {
        clearTimeout(timer);
        signal?.removeEventListener('abort', cancel);
      }
    },
  };
}

/** The assistant text of a response, ignoring reasoning blocks. */
export function responseText(response) {
  return (response?.content || []).filter(block => block.type === 'text').map(block => block.text).join('\n').trim();
}

export function toolCalls(response) {
  return (response?.content || []).filter(block => block.type === 'toolCall');
}

export function usageTokens(usage) {
  if (!usage) return 0;
  return Math.max(0, (usage.input || 0) + (usage.cacheRead || 0) + (usage.cacheWrite || 0) + (usage.output || 0));
}

