// Citation checking is code, not a model pass: a link the writer invented must
// never survive into the note as if it were a source.
import { wikilinkTarget } from './notes.mjs';

const LINK = /\[\[Sources\/[^\]|]+(?:\|[^\]]*)?\]\]/g;

/**
 * Keep only links that point at a source this turn was actually given.
 * Anything else becomes plain text plus a marker the note reports.
 */
export function checkCitations(noteBody, allowedRefs = []) {
  const allowed = new Set(allowedRefs.filter(Boolean).map(wikilinkTarget));
  const unresolved = [];
  let cited = 0;
  const body = String(noteBody ?? '').replace(LINK, match => {
    const target = wikilinkTarget(match);
    if (allowed.has(target)) { cited++; return match; }
    if (!unresolved.includes(target)) unresolved.push(target);
    const display = match.replace(/^\[\[/, '').replace(/\]\]$/, '').split('|')[1] || target.replace(/^Sources\//, '');
    return `${display} (unresolved source)`;
  });
  return { body, unresolved, cited };
}

/** The warning callout appended to a section, or an empty string. */
export function citationWarning(unresolved) {
  if (!unresolved || !unresolved.length) return '';
  const label = `${unresolved.length} citation${unresolved.length === 1 ? '' : 's'} could not be resolved`;
  return `> [!warning]- ${label}\n${unresolved.map(item => `> - ${item}`).join('\n')}`;
}

