/** Strict: a half-written answer must not reach a note looking authoritative. */
export function parseOutcome(text) {
  const value = String(text ?? '');
  const metaAt = value.indexOf(META_MARKER);
  const briefAt = value.indexOf(BRIEF_MARKER);
  const noteAt = value.indexOf(NOTE_MARKER);
