    return { error: 'The answer topics were not 1-5 kebab-case tags.' };
  }
  if (!['high', 'medium', 'low'].includes(meta.confidence)) return { error: 'The answer confidence was not high, medium or low.' };
  const open = meta.open === undefined ? [] : meta.open;
  if (!Array.isArray(open) || open.length > 3 || open.some(item => typeof item !== 'string' || !item.trim())) {
    return { error: 'The open questions were not up to three strings.' };
  }
