  const supportsImages = Array.isArray(caller.model?.input) && caller.model.input.includes('image');
  const blocks = supportsImages ? images.filter(image => image?.type === 'image') : [];
  const content = blocks.length ? [{ type: 'text', text: context.userContent }, ...blocks] : context.userContent;
  const messages = [{ role: 'user', content, timestamp: Date.now() }];
  const options = { systemPrompt: context.systemPrompt, tools: [], signal, maxTokens: MAX_OUTPUT_TOKENS, stallMs: 90_000, timeoutMs: 180_000, onEvent };

  let tokens = 0;
  let response = await caller.call({ messages: [...messages], ...options });
  tokens += usageTokens(response.usage);
  let parsed = parseOutcome(responseText(response));
  let repaired = false;
  if (parsed.error) {
    repaired = true;
    messages.push(response, { role: 'user', content: REPAIR, timestamp: Date.now() });
    response = await caller.call({ messages: [...messages], ...options });
    tokens += usageTokens(response.usage);
    parsed = parseOutcome(responseText(response));
  }
  if (parsed.outcome) return { outcome: parsed.outcome, tokens, repaired, warning: '' };
  return {
    outcome: fallbackOutcome(responseText(response), question), tokens, repaired,
    warning: 'Answer format was malformed; the note was saved without structure.',
  };
}

