// The crew: one router call decides whether the question needs sources, up to
// four researchers run in parallel with the web tools, and each returns a packet
// of claims with verbatim quotes and the exact source links the writer must reuse.
import { responseText, toolCalls, usageTokens } from './model.mjs';

export const MAX_WORKERS = 4;
export const MAX_TURNS = 8;
export const MAX_TOOL_CALLS = 6;
export const MAX_OUTPUT_TOKENS = 12_000;
const MAX_CALL_TOKENS = 6_000;
const ROUTE_TOKENS = 400;
const ROUTE_TIMEOUT = 45_000;
const WORKER_TIMEOUT = 90_000;

export const ROUTER_PROMPT = `You decide whether answering a question needs web research, and how to split it.
Return one JSON object and nothing else:
{"needsResearch": true, "queries": ["...", "..."], "reason": "one short sentence"}

needsResearch is false for questions answerable from general knowledge, reasoning, arithmetic, or the
conversation so far: definitions, explanations, derivations, opinions, code, mathematics, or anything the
conversation already established.
needsResearch is true when the answer depends on lookable facts that may have changed: numbers, dates,
current events, prices, versions, named people, products, studies, laws, or anything a reader would want
cited.
When true, write 2-4 search queries, each a different angle of the question, each 3-12 words, no quotes
and no search operators. When false, queries is [].`;

export const RESEARCHER_PROMPT = `You gather evidence for one question. You return evidence, not prose.
Use web_search to find candidate pages, then fetch_source on the pages most likely to hold the answer.
Rules:
- At most 6 tool calls. Fetch at least one source before answering unless every search failed.
- Every finding needs a claim (one sentence) and a quote copied verbatim from the fetched page text.
- Copy the "ref" field of a fetched source into every finding that uses it, character for character.
  Never write a ref you did not receive from fetch_source.
- Prefer primary sources, official documentation, papers and direct reporting over aggregators.
- Report what is missing or contradictory in "gaps" instead of guessing.
- Return one JSON object and nothing else:
{"findings": [{"claim": "...", "quote": "...", "ref": "[[Sources/...]]"}], "gaps": ["..."]}`;

function parseJson(text) {
  const value = String(text ?? '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const start = value.indexOf('{');
  const end = value.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error('No JSON object was returned.');
  return JSON.parse(value.slice(start, end + 1));
}

const abortReason = signal => (signal?.reason instanceof Error ? signal.reason : new Error('The turn was cancelled.'));

function cleanQueries(value) {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  const queries = [];
  for (const item of value) {
    const query = typeof item === 'string' ? item.replace(/\s+/g, ' ').trim() : '';
    if (query.length < 3 || query.length > 300 || seen.has(query.toLowerCase())) continue;
    seen.add(query.toLowerCase());
    queries.push(query);
    if (queries.length === MAX_WORKERS) break;
  }
  return queries;
}

/** One cheap call: does this question need sources, and which angles? */
export async function route({ caller, question, recent = '', signal }) {
  const messages = [{
    role: 'user',
    content: recent.trim()
      ? `Conversation so far:\n${recent.trim().slice(-4000)}\n\nQuestion: ${question}`
      : `Question: ${question}`,
    timestamp: Date.now(),
  }];
  const options = { systemPrompt: ROUTER_PROMPT, tools: [], signal, maxTokens: ROUTE_TOKENS, timeoutMs: ROUTE_TIMEOUT, stallMs: ROUTE_TIMEOUT };
  const decode = response => {
    const value = parseJson(responseText(response));
    const research = value.needsResearch === true || value.research === true;
    const queries = cleanQueries(value.queries);
    const reason = typeof value.reason === 'string' ? value.reason.trim().slice(0, 240) : '';
    if (research && !queries.length) return { research: false, queries: [], reason: reason || 'no usable queries' };
    return { research, queries, reason };
  };
  let response = await caller.call({ messages, ...options });
  try { return decode(response); }
  catch {
    if (signal?.aborted) throw abortReason(signal);
    try {
      response = await caller.call({ messages: [...messages, response, { role: 'user', content: 'Return only the JSON object.', timestamp: Date.now() }], ...options });
      return decode(response);
    } catch (error) {
      if (signal?.aborted) throw abortReason(signal);
      return { research: false, queries: [], reason: 'routing failed' };
    }
  }
}

function readPacket(text) {
  const value = parseJson(text);
  const findings = Array.isArray(value.findings) ? value.findings
    .filter(item => item && typeof item.claim === 'string' && item.claim.trim())
    .slice(0, 40)
    .map(item => ({
      claim: item.claim.trim().slice(0, 1200),
      quote: typeof item.quote === 'string' ? item.quote.trim().slice(0, 2000) : '',
      ref: typeof item.ref === 'string' ? item.ref.trim() : '',
    })) : [];
  const gaps = Array.isArray(value.gaps)
    ? value.gaps.filter(item => typeof item === 'string' && item.trim()).slice(0, 10).map(item => item.trim().slice(0, 400))
    : [];
  return { findings, gaps };
}

/**
 * One researcher: a bounded tool loop that ends in a JSON packet. Limits and
 * provider failures become `gaps` on the packet, never exceptions — a crew of
 * four must not die because one query hit a rate limit.
 */
export async function runWorker({ caller, query, tools, signal, onProgress, maxTurns = MAX_TURNS, maxToolCalls = MAX_TOOL_CALLS }) {
  const fetched = new Map();
  const toolMap = new Map();
  for (const tool of tools) {
    toolMap.set(tool.name, {
      ...tool,
      execute: async (callId, args, workerSignal) => {
        const result = await tool.execute(callId, args, workerSignal);
        const details = result?.details;
        if (details?.sourceId && (details.ref || details.sourceRef)) {
          fetched.set(details.sourceId, {
            id: details.sourceId, ref: details.ref || details.sourceRef,
            title: details.title || '', url: details.url || '', path: details.path || '',
          });
        }
        return result;
      },
    });
  }
  const definitions = tools.map(({ name, description, parameters }) => ({ name, description, parameters }));
  const messages = [{ role: 'user', content: `Question: ${query}`, timestamp: Date.now() }];
  const report = (state, extra = {}) => onProgress?.({ type: 'worker', query, state, ...extra });
  const finish = (packet, extra = {}) => ({ query, ...packet, toolCalls: extra.toolCalls || 0, tokens: extra.tokens || 0, sources: [...fetched.values()] });

  let tokens = 0;
  let used = 0;
  let last = null;
  report('searching');
  for (let turn = 1; turn <= maxTurns; turn++) {
    if (signal?.aborted) throw abortReason(signal);
    const remaining = MAX_OUTPUT_TOKENS - tokens;
    if (remaining < 256) return finish({ findings: [], gaps: ['The research budget was exhausted before a packet was returned.'] }, { toolCalls: used, tokens });
    let response;
    try {
      response = await caller.call({
        systemPrompt: RESEARCHER_PROMPT, messages: [...messages], tools: definitions, signal,
        maxTokens: Math.min(MAX_CALL_TOKENS, remaining), timeoutMs: WORKER_TIMEOUT, stallMs: WORKER_TIMEOUT,
        onEvent: kind => report(kind === 'tool' ? 'reading' : 'thinking'),
      });
    } catch (error) {
      if (signal?.aborted) throw abortReason(signal);
      return finish({ findings: [], gaps: [`Research call failed: ${error.message}`] }, { toolCalls: used, tokens });
    }
    tokens += usageTokens(response.usage);
    last = response;
    const calls = toolCalls(response);
    if (!calls.length) {
      if (response.stopReason === 'length') return finish({ findings: [], gaps: ['The research response hit its output limit.'] }, { toolCalls: used, tokens });
      let packet;
      try { packet = readPacket(responseText(response)); }
      catch {
        try {
          const repaired = await caller.call({
            systemPrompt: RESEARCHER_PROMPT,
            messages: [...messages, response, { role: 'user', content: 'Return only the JSON object.', timestamp: Date.now() }],
            tools: [], signal, maxTokens: MAX_CALL_TOKENS, timeoutMs: WORKER_TIMEOUT, stallMs: WORKER_TIMEOUT,
          });
          tokens += usageTokens(repaired.usage);
          packet = readPacket(responseText(repaired));
        } catch (error) {
          if (signal?.aborted) throw abortReason(signal);
          return finish({ findings: [], gaps: [`Packet malformed: ${error.message}`] }, { toolCalls: used, tokens });
        }
      }
      report(packet.findings.length ? 'done' : 'empty', { findings: packet.findings.length });
      return finish(packet, { toolCalls: used, tokens });
    }
    if (used + calls.length > maxToolCalls) return finish({ findings: [], gaps: ['The research tool budget was exhausted.'] }, { toolCalls: used, tokens });
    messages.push(response);
    for (const call of calls) {
      if (signal?.aborted) throw abortReason(signal);
      const tool = toolMap.get(call.name);
      used++;
      report('reading', { tool: call.name });
      if (!tool) {
        messages.push({ role: 'toolResult', toolCallId: call.id, toolName: call.name, content: [{ type: 'text', text: '{"error":"unknown-tool"}' }], isError: true, timestamp: Date.now() });
        continue;
      }
      let result;
      try { result = await tool.execute(call.id, call.arguments, signal); }
      catch (error) {
        if (signal?.aborted) throw abortReason(signal);
        result = { content: [{ type: 'text', text: JSON.stringify({ error: 'tool-failed' }) }], isError: true };
      }
      messages.push({
        role: 'toolResult', toolCallId: call.id, toolName: call.name,
        content: Array.isArray(result?.content) && result.content.length ? result.content : [{ type: 'text', text: '{"error":"empty-result"}' }],
        isError: Boolean(result?.isError), timestamp: Date.now(),
      });
    }
  }
  return finish({ findings: [], gaps: [`No packet after ${maxTurns} turns.`] }, { toolCalls: used, tokens });
}

/** Up to four researchers in parallel; one failure degrades one packet only. */
export async function runCrew({ caller, queries, tools, signal, onProgress }) {
  const selected = cleanQueries(queries);
  const total = selected.length;
  let done = 0;
  const sources = new Map();
  const packets = await Promise.all(selected.map(async (query, index) => {
    const controller = new AbortController();
    const cancel = () => controller.abort(signal?.reason ?? new Error('The turn was cancelled.'));
    if (signal) {
      if (signal.aborted) cancel();
      else signal.addEventListener('abort', cancel, { once: true });
    }
    try {
      const packet = await runWorker({
        caller, query, tools, signal: controller.signal,
        onProgress: event => onProgress?.({ ...event, index, done, total }),
      });
      for (const source of packet.sources) sources.set(source.id, source);
      done++;
      onProgress?.({ type: 'worker', query, state: 'done', findings: packet.findings.length, done, total, index });
      return packet;
    } catch (error) {
      if (signal?.aborted) throw abortReason(signal);
      done++;
      onProgress?.({ type: 'worker', query, state: 'failed', done, total, index });
      return { query, findings: [], gaps: [`Research worker failed: ${error.message}`], toolCalls: 0, tokens: 0, sources: [] };
    } finally {
      signal?.removeEventListener('abort', cancel);
    }
  }));
  return { packets, sources: [...sources.values()] };
}

