// The only module that touches the host UI. Everything here is best-effort: a
// display that disappears mid-turn must never fail a turn.
const KEY = 'discover';

export const STATUS_KEY = KEY;

export function createProgress(ctx) {
  const lines = [];
  const started = Date.now();
  let refresh = null;
  let open = false;

  const guard = work => { try { work(); } catch { /* A missing display is not a turn failure. */ } };
  const ui = () => ctx?.ui;
  const elapsed = () => Math.max(0, Math.round((Date.now() - started) / 1000));
  const paint = () => guard(() => refresh?.());

  return {
    begin() {
      lines.length = 0;
      open = true;
      guard(() => {
        if (!ctx?.hasUI || typeof ui().setWidget !== 'function') return;
        ui().setWidget(KEY, tui => {
          refresh = () => tui.requestRender();
          return { render: () => (lines.length ? lines : undefined), invalidate() {} };
        });
      });
    },
    status(text) {
      guard(() => { if (ctx?.hasUI) ui().setStatus(KEY, `${KEY} · ${text} · ${elapsed()}s`); });
    },
    /** One line per researcher, updated in place as the crew works. */
    worker(event = {}) {
      const query = String(event.query || '').replace(/\s+/g, ' ').slice(0, 44);
      const state = event.state === 'done' && event.findings
        ? `done (${event.findings} finding${event.findings === 1 ? '' : 's'})`
        : event.state || 'working';
      const line = `${query} — ${state}`;
      const at = lines.findIndex(existing => existing.startsWith(`${query} —`));
      if (at === -1) lines.push(line);
      else lines[at] = line;
      const done = Number.isInteger(event.done) ? event.done : 0;
      const total = Number.isInteger(event.total) ? event.total : lines.length;
      if (total) guard(() => { if (ctx?.hasUI) ui().setStatus(KEY, `${KEY} · researching ${done}/${total} · ${elapsed()}s`); });
      paint();
    },
    note(text) {
      lines.push(String(text));
      paint();
    },
    finish({ sources = 0, tokens = 0 } = {}) {
      open = false;
      refresh = null;
      guard(() => {
        if (!ctx?.hasUI) return;
        if (typeof ui().setWidget === 'function') ui().setWidget(KEY, undefined);
        const parts = [`${sources} source${sources === 1 ? '' : 's'}`];
        if (tokens) parts.push(`${Math.round(tokens / 100) / 10}k tok`);
        parts.push(`${elapsed()}s`);
        ui().setStatus(KEY, `${KEY} · ${parts.join(' · ')}`);
      });
    },
    clear() {
      open = false;
      refresh = null;
      lines.length = 0;
      guard(() => {
        if (!ctx?.hasUI) return;
        if (typeof ui().setWidget === 'function') ui().setWidget(KEY, undefined);
        ui().setStatus(KEY, undefined);
      });
    },
    get active() { return open; },
  };
}

