// The derived index that makes related-chat links and source reuse cheap: no
// vault scan per turn, no scan per keystroke of /discover pick. `_discover/index.json`
// is always rebuildable from `_discover/chats/*.json` and the source notes.
import { parseFrontmatter } from './notes.mjs';

const INDEX_PATH = '_discover/index.json';
const ACTIVE_PATH = '_discover/active.json';
const CHATS_DIR = '_discover/chats';
const HASH = /^[0-9a-f]{64}$/;

const jsonText = value => `${JSON.stringify(value, null, 2)}\n`;

function emptyIndex() {
  return { version: 1, updatedAt: new Date().toISOString(), chats: {}, sources: {} };
}

function validIndex(value) {
  return value && value.version === 1 && value.chats && typeof value.chats === 'object'
    && value.sources && typeof value.sources === 'object' && !Array.isArray(value.chats) && !Array.isArray(value.sources);
}

/** Records are stored newest-first so list views never sort on read. */
const byUpdated = (left, right) => String(right.updatedAt || '').localeCompare(String(left.updatedAt || ''));

export function createIndex(vault) {
  let cache = null;

  async function readJson(relative) {
    try { return JSON.parse(await vault.readFile(relative)); }
    catch (error) { if (error.code === 'ENOENT' || error instanceof SyntaxError) return null; throw error; }
  }

  /** Derived data must never be authoritative: recover rather than fail a turn. */
  async function rebuild() {
    const index = emptyIndex();
    for (const entry of await vault.listDir(CHATS_DIR)) {
      if (entry.isDirectory || !entry.name.endsWith('.json')) continue;
      const record = await readJson(`${CHATS_DIR}/${entry.name}`);
      if (!record || typeof record.id !== 'string' || typeof record.notePath !== 'string') continue;
      index.chats[record.id] = {
        path: record.notePath, title: record.title || 'Untitled chat', topics: record.topics || [],
        sources: record.sources || [], updatedAt: record.updatedAt || record.createdAt || new Date().toISOString(),
      };
    }
    for (const entry of await vault.listDir('Sources')) {
      if (entry.isDirectory || !entry.name.endsWith('.md')) continue;
      let parsed;
      try { parsed = parseFrontmatter(await vault.readFile(`Sources/${entry.name}`)); }
      catch { continue; }
      const { data } = parsed;
      if (data.discover !== 'source' || !HASH.test(String(data.hash || ''))) continue;
      index.sources[data.hash] = {
        path: `Sources/${entry.name}`, url: data.url || '', title: data.title || entry.name.replace(/\.md$/, ''),
        kind: data.kind === 'pdf' ? 'pdf' : 'web', hash: data.hash, retrievedAt: data.retrieved || '',
      };
    }
    return index;
  }

  async function load({ force = false } = {}) {
    if (cache && !force) return cache;
    const stored = await readJson(INDEX_PATH);
    if (validIndex(stored)) { cache = stored; return cache; }
    cache = await rebuild();
    await save();
    return cache;
  }

  async function save() {
    if (!cache) return;
    cache.updatedAt = new Date().toISOString();
    await vault.writeFile(INDEX_PATH, jsonText(cache));
  }

  async function upsertChat(index, record) {
    for (const [id, entry] of Object.entries(index.chats)) {
      if (id !== record.id && entry.path === record.notePath) delete index.chats[id];
    }
    index.chats[record.id] = {
      path: record.notePath, title: record.title, topics: record.topics || [],
      sources: record.sources || [], updatedAt: record.updatedAt,
    };
  }

  return {
    async chats() {
      const index = await load();
      return Object.entries(index.chats).map(([id, entry]) => ({ id, ...entry })).sort(byUpdated);
    },
    async getChat(id) {
      const index = await load();
      const entry = index.chats[id];
      return entry ? { id, ...entry } : null;
    },
    async getSource(id) {
      const index = await load();
      const entry = index.sources[id];
      return entry ? { id, ...entry } : null;
    },
    async findSourceByUrl(url) {
      const index = await load();
      const normalized = String(url || '').trim();
      for (const [id, entry] of Object.entries(index.sources)) {
        if (entry.kind === 'web' && entry.url === normalized) return id;
      }
      return null;
    },
    async upsertSource(record) {
      const index = await load();
      for (const [id, entry] of Object.entries(index.sources)) {
        if (id !== record.id && entry.path === record.path) delete index.sources[id];
      }
      index.sources[record.id] = {
        path: record.path, url: record.url || '', title: record.title || '',
        kind: record.kind === 'pdf' ? 'pdf' : 'web', hash: record.id, retrievedAt: record.retrievedAt || new Date().toISOString(),
      };
      await save();
    },
    async saveChat(record) {
      const index = await load();
      await vault.writeFile(`${CHATS_DIR}/${record.id}.json`, jsonText({ version: 1, ...record }));
      await upsertChat(index, record);
      await save();
    },
    async setActive(chatId) {
      await vault.writeFile(ACTIVE_PATH, jsonText({ version: 1, chatId }));
    },
    async getActive() {
      const value = await readJson(ACTIVE_PATH);
      return value && typeof value.chatId === 'string' ? value.chatId : null;
    },
    async related(chatId, limit = 3) {
      const index = await load();
      const mine = index.chats[chatId];
      if (!mine) return [];
      const mySources = new Set(mine.sources || []);
      const myTopics = new Set(mine.topics || []);
      const scored = [];
      for (const [id, entry] of Object.entries(index.chats)) {
        if (id === chatId) continue;
        const shared = (entry.sources || []).filter(source => mySources.has(source));
        const topics = (entry.topics || []).filter(topic => myTopics.has(topic));
        if (shared.length < 2 && topics.length < 3) continue;
        const first = shared.length ? index.sources[shared[0]] : null;
        scored.push({
          id, path: entry.path, title: entry.title, updatedAt: entry.updatedAt,
          score: shared.length * 10 + topics.length,
          reason: shared.length
            ? `shares [[${(first?.path || `Sources/${shared[0]}`).replace(/\.md$/, '')}]]`
            : `shares ${topics.length} topics`,
        });
      }
      scored.sort((left, right) => (right.score - left.score) || String(right.updatedAt).localeCompare(String(left.updatedAt)));
      return scored.slice(0, Math.max(0, limit));
    },
    rebuild,
  };
}

