// The vault layer: path confinement, atomic writes, the single-writer lock, the
// chat/source note formats and everything derived from them. Nothing above this
// module touches the filesystem directly.
import * as fs from 'node:fs/promises';
import * as os from 'node:os';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import {
  CHAT_DIR, DISCOVER_DIR, MARKERS, SOURCE_DIR,
  frontmatter, normalizeObsidianMarkdown, parseFrontmatter, refsBlock,
  rewriteBlock, sanitizeTitle, sourceFileName, sourceRef, uniquePath,
} from './notes.mjs';
import { createIndex } from './index-store.mjs';

const locks = new Map();
const ID = /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/;
const HASH = /^[0-9a-f]{64}$/;
const META_PATH = `${DISCOVER_DIR}/vault.json`;
const LEGACY_META = '_Research/vault.json';
const LOCK_PATH = `${DISCOVER_DIR}/writer.lock`;
const PDF_DIR = `${DISCOVER_DIR}/pdf`;
const MAX_SOURCE_TEXT = 24000;

const now = () => new Date().toISOString();
const slash = value => value.replaceAll('\\', '/');
const fold = value => (process.platform === 'win32' ? value.toLowerCase() : value);
const samePath = (a, b) => fold(path.resolve(a)) === fold(path.resolve(b));
const hash = value => createHash('sha256').update(value).digest('hex');
const within = (root, target) => {
  const relative = path.relative(fold(root), fold(target));
  return relative === '' || (!relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative));
};
const jsonText = value => `${JSON.stringify(value, null, 2)}\n`;

async function serialized(key, work) {
  const previous = locks.get(key) || Promise.resolve();
  const current = previous.catch(() => {}).then(work);
  locks.set(key, current);
  try { return await current; }
  finally { if (locks.get(key) === current) locks.delete(key); }
}

async function optional(work) {
  try { return await work(); }
  catch (error) { if (error.code === 'ENOENT') return null; throw error; }
}

function relativePath(value) {
  if (typeof value !== 'string' || !value || value.includes('\0')) throw new Error('A vault-relative path is required');
  const normalized = slash(value);
  const parts = normalized.split('/');
  if (path.isAbsolute(value) || path.win32.isAbsolute(value) || normalized.startsWith('/') || parts.some(part => part === '..' || part.includes(':'))) {
    throw Object.assign(new Error('Path must remain inside the linked vault'), { code: 'ERR_PATH_ESCAPE' });
  }
  if (parts.some(part => part && part !== '.' && /[. ]$/.test(part))) throw new Error('Path segments must not end with a dot or space');
  const clean = parts.filter(part => part && part !== '.').join('/');
  if (!clean) throw new Error('A file path inside the vault is required');
  return clean;
}

async function potentialRealPath(input) {
  let candidate = path.resolve(input);
  const suffix = [];
  for (;;) {
    try { return path.join(await fs.realpath(candidate), ...suffix.reverse()); }
    catch (error) {
      if (error.code !== 'ENOENT') throw error;
      const parent = path.dirname(candidate);
      if (parent === candidate) throw error;
      suffix.push(path.basename(candidate));
      candidate = parent;
    }
  }
}

async function vaultRoot(input) {
  if (typeof input !== 'string' || !input.trim()) throw new Error('Select an existing Obsidian vault');
  const resolved = path.resolve(input);
  const root = await fs.realpath(resolved).catch(error => {
    if (error.code === 'ENOENT') throw new Error('That vault folder does not exist.');
    throw error;
  });
  if (!(await fs.stat(root)).isDirectory()) throw new Error('That vault folder does not exist.');
  const obsidian = await potentialRealPath(path.join(root, '.obsidian'));
  if (!within(root, obsidian) || !(await optional(() => fs.stat(obsidian)))?.isDirectory()) {
    throw new Error('The selected folder must contain its own .obsidian directory');
  }
  return root;
}

/** Lowercase host, no fragment, no tracking parameters, sorted query. */
export function normalizeUrl(value) {
  const url = new URL(String(value));
  url.hash = '';
  for (const key of [...url.searchParams.keys()]) {
    if (/^(utm_|fbclid$|gclid$|ref$|mc_cid$|mc_eid$)/i.test(key)) url.searchParams.delete(key);
  }
  url.searchParams.sort();
  const query = url.searchParams.toString();
  const pathname = url.pathname === '/' ? '' : url.pathname.replace(/\/$/, '');
  return `${url.protocol.toLowerCase()}//${url.hostname.toLowerCase()}${url.port ? `:${url.port}` : ''}${pathname}${query ? `?${query}` : ''}`;
}

const alive = pid => {
  try { process.kill(pid, 0); return true; }
  catch (error) { return error.code === 'EPERM'; }
};

/**
 * One vault, one writer. Every path is vault-relative and confined; every write
 * is atomic and serialized per path so two turns cannot interleave a file.
 */
export class Vault {
  constructor(root, { expectedId } = {}) {
    this.root = root;
    this.id = null;
    this.expectedId = expectedId || null;
    this.lockToken = null;
    this.skippedChats = [];
    this.index = createIndex(this);
  }

  async ensure() {
    for (const dir of [DISCOVER_DIR, `${DISCOVER_DIR}/chats`, PDF_DIR, CHAT_DIR, SOURCE_DIR]) {
