    }
    let meta = await this.readJson(META_PATH).catch(() => null);
    if (!meta || meta.version !== 1 || !ID.test(String(meta.id || ''))) {
      const legacy = await this.readJson(LEGACY_META).catch(() => null);
      const id = legacy && ID.test(String(legacy.id || '')) ? legacy.id : randomUUID();
      meta = { version: 1, id, createdAt: now() };
      await this.writeJson(META_PATH, meta);
    }
    if (this.expectedId && meta.id !== this.expectedId) {
      throw new Error('Discover vault identity does not match the saved binding');
    }
    this.id = meta.id;
    return this;
  }

  /** Resolves existing symlinks/junctions and rejects escape. Does not create anything. */
  async safePath(relative) {
    const clean = relativePath(relative);
    const currentRoot = await fs.realpath(this.root);
    if (!samePath(currentRoot, this.root)) throw new Error('The linked vault location has changed');
    let resolved = currentRoot;
    const parts = clean.split('/');
