// The chat: one running note per conversation, one turn at a time. The turn is
// routed, researched by a small crew, written once, checked in code, then saved.
import { randomUUID } from 'node:crypto';
import {
  CHAT_DIR, VOICE_PATH, appendExchange, callout, chatNoteHeader, dateStamp,
  formatTimestamp, normalizeObsidianMarkdown, recentExchanges, relatedBlock,
  replaceHeader, rewriteBlock, sanitizeTitle, uniquePath,
} from './notes.mjs';
import { createAttachments } from './attachments.mjs';
import { createModelCaller } from './model.mjs';
import { route, runCrew } from './research.mjs';
import { writeAnswer } from './answer.mjs';
import { checkCitations, citationWarning } from './citations.mjs';
import { createWebTools } from './tools.mjs';

const TURN_TIMEOUT = 5 * 60_000;
const MODEL_INPUT_PROMPT = 'The selected model cannot read images; the attachment was ignored.';

const modelLabel = model => (model?.provider ? `${model.provider}/${model.id}` : String(model?.id || 'model'));
const plural = (count, noun) => `${count} ${noun}${count === 1 ? '' : 's'}`;

/**
 * A turn owns the vault lock, the abort signal and the note write. Nothing is
 * written until the answer exists, so a failed or cancelled turn leaves the note
 * exactly as it was.
 */
export class Chat {
  constructor({ vault, progress, host }) {
    this.vault = vault;
    this.progress = progress;
    this.host = host || {};
    this.attachments = createAttachments({ vault });
    this.record = null;
    this.explicitTitle = null;
    this.turn = null;
  }

  get busy() { return Boolean(this.turn); }
  get title() { return this.record?.title || 'New chat'; }
  get notePath() { return this.record?.notePath || null; }
  get staged() { return this.attachments.list(); }

  async stage(file) { return this.attachments.stage(file); }
  clearAttachments() {
    this.attachments.clear();
    return true;
  }

  /** Reconnect to the active chat, or start a fresh one when asked. */
  async open({ title, fresh = false } = {}) {
    await this.vault.ensure();
    if (!fresh) {
      const active = await this.vault.getActive();
      const record = active ? await this.vault.getChatRecord(active) : null;
      if (record) {
        this.record = await this.repair(record);
        this.explicitTitle = null;
        await this.vault.setActive(this.record.id);
        return this.record;
      }
    }
    return this.start({ title });
  }

  start({ title } = {}) {
    const at = new Date().toISOString();
    this.explicitTitle = title ? sanitizeTitle(title) : null;
    this.record = {
      id: randomUUID(), title: this.explicitTitle, notePath: null,
      createdAt: at, updatedAt: at, model: null, topics: [], sources: [], turns: 0,
    };
    return this.record;
  }

  /** Reopen a chat the user picked; a moved note is found again by its id. */
  async select(chatId) {
    const record = await this.vault.getChatRecord(chatId);
    if (!record) throw new Error('That chat is no longer in the vault.');
    this.record = await this.repair(record);
    this.explicitTitle = null;
    await this.vault.setActive(this.record.id);
    return this.record;
  }

  async repair(record) {
    if (record.notePath && await this.vault.exists(record.notePath)) return record;
    const found = await this.vault.findChatNote(record.id);
    if (found) record.notePath = found;
    return record;
  }

  async stop() {
    const turn = this.turn;
    if (!turn) return false;
    turn.controller.abort(new Error('Stopped by /discover stop.'));
    return true;
  }

  async close() {
    await this.stop();
    await this.vault.releaseLock().catch(() => {});
  }

  async runTurn({ text, images = [], ctx }) {
    const question = String(text ?? '').trim();
    const pasted = Array.isArray(images) ? images.filter(image => image?.type === 'image') : [];
    if (!question && !pasted.length) return null;
    if (this.busy) throw new Error('Still working. Your draft is preserved; /discover stop interrupts.');
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(new Error('The turn exceeded its five minute limit.')), TURN_TIMEOUT);
    timer.unref?.();
    this.turn = { controller, started: Date.now() };
    this.progress.begin();
    try {
      return await this.turnOnce({ question, pasted, ctx, signal: controller.signal });
    } finally {
      clearTimeout(timer);
      this.turn = null;
      this.progress.clear();
      await this.vault.releaseLock().catch(() => {});
    }
  }

  async turnOnce({ question, pasted, ctx, signal }) {
    await this.vault.ensure();
    await this.vault.acquireLock();
    if (!this.record) await this.open();
    const noteText = (await this.vault.readChatNote(this.record)) || '';
    const recent = recentExchanges(noteText, 3, 6000);
    const staged = await this.attachments.evidence({ question, model: ctx.model, signal });
    const sources = new Map(staged.sources.map(source => [source.id, source]));

    const images = [...pasted, ...staged.images];
    const readable = Array.isArray(ctx.model?.input) && ctx.model.input.includes('image');
    if (images.length && !readable) ctx.ui.notify(MODEL_INPUT_PROMPT, 'warning');

    const caller = createModelCaller({ registry: ctx.modelRegistry, model: ctx.model, thinkingLevel: ctx.thinkingLevel });
    this.progress.status('routing');
    const decision = await route({ caller, question, recent: recent, signal });
    let packets = [];
    if (decision.research) {
      const tools = createWebTools({ vault: this.vault });
      const crew = await runCrew({
        caller, queries: decision.queries, tools, signal,
        onProgress: event => this.progress.worker(event),
      });
      packets = crew.packets;
      for (const source of crew.sources) sources.set(source.id, source);
    }

    this.progress.status('writing');
    const voice = await this.vault.readFile(VOICE_PATH).catch(() => '');
    const answer = await writeAnswer({
      caller, question, recent, packets,
      attachmentText: staged.text, voice,
      images: readable ? images : [],
      signal,
      onEvent: kind => this.progress.status(kind === 'thinking' ? 'thinking' : 'writing'),
    });

    const normalized = normalizeObsidianMarkdown(answer.outcome.note);
    const allowed = [...sources.values()].map(source => source.ref);
    const checked = checkCitations(normalized, allowed);
    const cited = [...sources.values()].filter(source => checked.body.includes(source.ref));
    const sectionWarnings = [citationWarning(checked.unresolved), answer.warning ? callout('warning', answer.warning) : ''].filter(Boolean);
    const index = (this.record.turns || 0) + 1;
    const model = modelLabel(ctx.model);

    if (!this.record.notePath) {
      const title = this.explicitTitle || answer.outcome.meta.title || sanitizeTitle(question);
      this.record.title = title;
      this.record.notePath = await uniquePath(candidate => this.vault.exists(candidate), CHAT_DIR, `${dateStamp()} ${sanitizeTitle(title)}`, '.md');
    }
    this.record.topics = [...new Set([...(this.record.topics || []), ...answer.outcome.meta.topics])].slice(0, 12);
    this.record.sources = [...new Set([...(this.record.sources || []), ...cited.map(source => source.id)])];
    this.record.model = model;
    this.record.updatedAt = new Date().toISOString();
    this.record.turns = index;

    const provenance = cited.length
      ? callout('info', `Asked ${formatTimestamp()} · ${plural(cited.length, 'source')} · ${model}`, cited.map(source => source.ref).join(' · '))
      : callout('info', `Asked ${formatTimestamp()} · no sources · ${model}`, 'Answered from the conversation and general knowledge.');

    this.progress.status('saving note');
    let text = noteText || chatNoteHeader(this.record, { sourceCount: 0 });
    text = appendExchange(text, {
      index, question, provenance,
      body: [checked.body, ...sectionWarnings].join('\n\n'),
    });
    const related = await this.vault.relatedChats(this.record.id, { limit: 3 });
    text = rewriteBlock(text, 'related', relatedBlock(related.map(entry => ({ path: entry.path, reason: entry.reason }))));
    text = replaceHeader(text, chatNoteHeader(this.record, { sourceCount: this.record.sources.length }));
    await this.vault.writeChatNote(this.record, text);

    await this.vault.saveChat(this.record);
    for (const source of cited) await this.vault.noteSourceReference(source.id, this.record.notePath);
    await this.vault.setActive(this.record.id);
    this.attachments.clear();

    const tokens = (decision.tokens || 0) + answer.tokens + packets.reduce((sum, packet) => sum + (packet.tokens || 0), 0);
    this.progress.finish({ sources: cited.length, tokens });
    this.host.sendBrief?.(answer.outcome.brief);
    return {
      brief: answer.outcome.brief, notePath: this.record.notePath, chatId: this.record.id,
      sources: cited.length, unresolved: checked.unresolved, tokens,
    };
  }
}

