{"content": "// One static catalogue keeps completions, help and accepted command names in
// sync. Browsing it must not read a vault, load the SDK or start a turn.
export const DISCOVER_COMMANDS = Object.freeze([
  { name: '', description: 'Open Discover; reconnect to the linked vault and reopen the active chat.' },
  { name: 'attach', args: '"file path"', description: 'Stage a file (PDF) for the next message.' },
  { name: 'clear', description: 'Clear staged files.' },
  { name: 'exit', description: 'Close Discover and release the vault.' },
  { name: 'help', args: '[command]', description: 'Show this guide, or help for one command.' },
  { name: 'new', args: '[title]', description: 'Start a new chat, with an optional title.' },
  { name: 'pick', description: 'Choose a previous chat to reopen.' },
  { name: 'stop', description: 'Stop the answer in progress; the note is untouched.' },
  { name: 'unlock', description: 'Clear a stale vault lock left by an unclean exit.' },
  { name: 'vault', args: '"folder path"', description: 'Link an Obsidian vault, or switch to a different one.' },
].map(item => Object.freeze(item)));

export const usage = item => `/discover${item.name ? ` ${item.name}` : ''}${item.args ? ` ${item.args}` : ''}`;

/** Split a command line; a quoted argument keeps its spaces and loses its quotes. */
export function parseCommand(input) {
  const match = String(input ?? '').trim().match(/^(\S+)?\s*([\s\S]*)$/);
  let argument = (match?.[2] || '').trim();
  if (argument.length >= 2 && ((argument.startsWith('"') && argument.endsWith('"')) || (argument.startsWith("'") && argument.endsWith("'")))) {
    argument = argument.slice(1, -1);
  }
  return { command: (match?.[1] || '').toLowerCase(), argument };
}

export function getDiscoverArgumentCompletions(prefix) {
  const input = String(prefix ?? '').trimStart();
  const help = /^help\s+(\S*)$/i.exec(input);
  if (!help && /\s/.test(input)) return null; // Preserve paths and titles.
  const query = (help ? help[1] : input).toLowerCase();
  const matches = DISCOVER_COMMANDS.filter(item => item.name.startsWith(query));
  return matches.length ? matches.map(item => ({
    value: help ? `help ${item.name}` : item.name + (item.args ? ' ' : ''),
    label: item.name || '/discover',
    description: item.description,
  })) : null;
}

export function discoverHelp(topic = '') {
  const name = String(topic ?? '').trim().toLowerCase();
  if (name) {
    const command = DISCOVER_COMMANDS.find(item => item.name === name);
    if (!command) throw new Error('Unknown help topic. Use /discover help to see all commands.');
    return `Discover: ${name}\n\n${usage(command)}\n${command.description}\n\n<...> is required; [...] is optional. Quote paths or titles containing spaces.\n/discover help shows the full guide.`;
  }
  const lines = DISCOVER_COMMANDS.map(item => `${usage(item)}\n  ${item.description}`);
  return `Discover: ask in Pi; every answer lands in one note in your Obsidian vault.\nType /discover followed by a space to browse commands.\n\n${lines.join('\n')}\n\n<...> is required; [...] is optional. Quote paths or titles containing spaces.\nFirst use: /discover vault "C:\\path\\to\\Vault"\nExample: /discover attach "C:\\Papers\\study.pdf"`;
}
