// The Pi contract: one command, one input hook, one close path. Everything the
// turn does lives in chat.mjs; this file only translates host events into it.
import { openVault } from './vault.mjs';
import { readConfig, writeConfig, scholarOwnsInput, scholarRoots } from './config.mjs';
import { DISCOVER_COMMANDS, discoverHelp, getDiscoverArgumentCompletions, parseCommand } from './commands.mjs';
import { createProgress } from './progress.mjs';
import { Chat } from './chat.mjs';

const NO_VAULT = 'Link an existing vault first: /discover vault "C:\\path\\to\\Vault"\nUse /discover help for setup and all commands.';
const BUSY_SWITCH = 'Use /discover stop before changing the active chat.';

export function registerDiscover(pi) {
  let chat = null;
  let vault = null;
  let lastContext = null;
  let starting = false;
  let closing = false;
  let operation = Promise.resolve();
  let closePromise = null;

  const notify = (ctx, message, level = 'info') => ctx.ui.notify(message, level);

  function ready(ctx, { switching = false } = {}) {
    if (!ctx.isIdle()) throw new Error('Finish or stop the current Pi turn before entering Discover.');
    if (scholarOwnsInput(ctx.sessionManager.getBranch())) throw new Error('Leave the active Scholar mode before entering Discover.');
    if (switching && chat?.busy) throw new Error(BUSY_SWITCH);
  }

  async function linkedVault() {
    const config = await readConfig();
    if (!config) throw new Error(NO_VAULT);
    const instance = await openVault(config.vaultRoot, { scholarRoots: await scholarRoots(), expectedId: config.vaultId });
    await instance.ensure();
    return instance;
  }

  /** The open session, created lazily so browsing /discover help stays free. */
  async function session() {
    if (chat && vault) return chat;
    vault = await linkedVault();
    chat = new Chat({
      vault,
      host: {
        progress: ctx => createProgress(ctx),
        sendBrief: brief => pi.sendMessage({ customType: 'discover', content: brief, display: true }, { triggerTurn: false }),
      },
    });
    return chat;
  }

  async function close(ctx) {
    if (closing) return closePromise;
    if (!chat && !vault) return;
    closing = true;
    closePromise = (async () => {
      const previous = chat;
      chat = null;
      vault = null;
      try { await previous?.close(); }
      finally {
        closing = false;
        closePromise = null;
        (ctx || lastContext)?.ui.setStatus('discover', undefined);
      }
    })();
    return closePromise;
  }

  async function link(ctx, input) {
    const instance = await openVault(input, { scholarRoots: await scholarRoots() });
    await instance.ensure();
    if (chat) await close(ctx);
    vault = instance;
    return instance;
  }

  async function choose(ctx, active) {
    const chats = await vault.listChats();
    for (const title of vault.skippedChats) notify(ctx, `${title}: note file is missing; the chat was skipped.`, 'warning');
    if (!chats.length) throw new Error('There are no chats in this vault yet.');
    const labels = chats.map(chatRecord => {
      const date = String(chatRecord.updatedAt || '').slice(0, 10);
      return `${date} · ${chatRecord.title} · ${chatRecord.path}`;
    });
    const selected = await ctx.ui.select('Reopen a Discover chat', labels);
    if (!selected) return null;
    return active.select(chats[labels.indexOf(selected)].id);
  }

  async function execute(command, argument, ctx) {
    ready(ctx, { switching: ['new', 'pick', 'vault'].includes(command) });

    if (command === 'vault') {
      if (!argument) throw new Error('Provide the path of an existing Obsidian vault.');
      const instance = await link(ctx, argument);
      await writeConfig({ vaultRoot: instance.root, vaultId: instance.id });
      notify(ctx, 'Vault linked. Type a question in Pi; the answer lands in Chats/ and its sources in Sources/.');
      return;
    }
    if (command === 'unlock') {
      const instance = vault || await linkedVault();
      const cleared = await instance.unlockStale();
      notify(ctx, cleared ? 'Stale writer lock cleared.' : 'No writer lock was present.');
      return;
    }
    if (command === 'exit') {
      await close(ctx);
      notify(ctx, 'Discover closed. Ordinary Pi input is restored.');
      return;
    }
    if (command === 'stop') {
      if (!chat) throw new Error('Open Discover with /discover first.');
      notify(ctx, (await chat.stop()) ? 'Stopping. The note is untouched.' : 'Nothing is running.');
      return;
    }
    if (command === 'attach') {
      if (!argument) throw new Error('Provide a file path to stage.');
      const active = await session();
      const staged = await active.stage(argument);
      notify(ctx, `Staged ${staged.length} file(s): ${staged.join(', ')}. They are attached to your next question.`);
      return;
    }
    if (command === 'clear') {
      const active = await session();
      active.clearAttachments();
      notify(ctx, 'Staged files cleared.');
      return;
    }

    const active = await session();
    if (command === 'new') {
      active.start({ title: argument });
      notify(ctx, argument ? `New chat: ${argument}. Type your question in Pi.` : 'New chat. Type your question in Pi.');
      return;
    }
    if (command === 'pick') {
      const record = await choose(ctx, active);
      if (!record) return;
      notify(ctx, `Reopened ${record.title}. Type your next question in Pi.`);
      return;
    }
    const record = await active.open();
    const staged = active.staged;
    notify(ctx, [
      `Discover ready · ${record.title || 'new chat'}`,
      record.notePath ? `Note: ${record.notePath}` : 'The note is written with your first answer.',
      staged.length ? `Staged: ${staged.join(', ')}` : '',
      'Type your question in Pi. /discover help lists the commands; /discover exit returns to ordinary Pi input.',
    ].filter(Boolean).join('\n'));
  }

  pi.registerCommand('discover', {
    description: 'Ask in Pi; every answer lands in one note in your Obsidian vault. /discover help lists commands.',
    getArgumentCompletions: getDiscoverArgumentCompletions,
    handler: async (args, ctx) => {
      const { command, argument } = parseCommand(args);
      try {
        if (command && !DISCOVER_COMMANDS.some(item => item.name === command)) throw new Error('Unknown Discover command. Use /discover help.');
        if (command === 'help') { notify(ctx, discoverHelp(argument)); return; }
        lastContext = ctx;
        starting = true;
        operation = execute(command, argument, ctx)
          .catch(error => notify(ctx, error.message || String(error), 'error'))
          .finally(() => { starting = false; });
        await operation;
      } catch (error) { notify(ctx, error.message || String(error), 'error'); }
    },
  });

  pi.on('input', (event, ctx) => {
    if (!chat || closing || event.source === 'extension') return { action: 'continue' };
    lastContext = ctx;
    if (scholarOwnsInput(ctx.sessionManager.getBranch())) {
      notify(ctx, 'Discover input is paused while Scholar is active. Exit Scholar or /discover exit.', 'warning');
      return { action: 'continue' };
    }
    const current = chat;
    if (starting || current.busy) {
      if (!ctx.ui.getEditorText()) ctx.ui.setEditorText(event.text);
      notify(ctx, 'Still working. Your draft is preserved; /discover stop interrupts.', 'warning');
      return { action: 'handled' };
    }
    void current.runTurn({ text: event.text, images: event.images || [], ctx }).catch(error => {
      if (chat !== current || closing) return;
      if (!ctx.ui.getEditorText()) ctx.ui.setEditorText(event.text);
      notify(ctx, error.message || String(error), /cancel|stopped by/i.test(String(error?.message)) ? 'warning' : 'error');
    });
    return { action: 'handled' };
  });

  pi.on('session_start', (_event, ctx) => close(ctx));
  pi.on('session_shutdown', (_event, ctx) => close(ctx));
}

