import test from 'node:test';
import assert from 'node:assert/strict';
import { checkCitations, citationWarning } from '../src/citations.mjs';

const A = '[[Sources/Alpha (aaaaaaaa)|Alpha]]';
const B = '[[Sources/Beta (bbbbbbbb)|Beta]]';

test('a link that points at a known source survives untouched', () => {
  const { body, unresolved, cited } = checkCitations(`Claim. ${A}`, [A]);
  assert.equal(body, `Claim. ${A}`);
  assert.deepEqual(unresolved, []);
  assert.equal(cited, 1);
});

test('an invented link becomes plain text and is reported', () => {
  const { body, unresolved, cited } = checkCitations(`Claim. [[Sources/Nope (00000000)|Nope]] done.`, [A]);
  assert.equal(body, 'Claim. Nope (unresolved source) done.');
  assert.deepEqual(unresolved, ['Sources/Nope (00000000)']);
  assert.equal(cited, 0);
});

test('mixed links keep the real ones and count them', () => {
  const text = `${A} and ${B} and [[Sources/Fake (deadbeef)|Fake]] and ${A}`;
  const { body, unresolved, cited } = checkCitations(text, [A, B]);
  assert.equal(cited, 3);
  assert.deepEqual(unresolved, ['Sources/Fake (deadbeef)']);
  assert.ok(body.includes(A) && body.includes(B));
  assert.ok(body.includes('Fake (unresolved source)'));
});

test('a link without display text falls back to its target name', () => {
  const { body } = checkCitations('See [[Sources/Gone (12345678)]].', []);
  assert.equal(body, 'See Gone (12345678) (unresolved source).');
});

test('the warning callout states the count and lists each target once', () => {
  const warning = citationWarning(['Sources/X (1)', 'Sources/Y (2)']);
  assert.ok(warning.startsWith('> [!warning]- 2 citations could not be resolved'));
  assert.ok(warning.includes('> - Sources/X (1)'));
  assert.equal(citationWarning([]), '');
  assert.ok(citationWarning(['Sources/X (1)']).startsWith('> [!warning]- 1 citation could not be resolved'));
});

