import test from 'node:test';
import assert from 'node:assert/strict';
import { MAX_TOOL_CALLS, route, runCrew, runWorker } from '../src/research.mjs';

const PACKET = JSON.stringify({
  findings: [{ claim: 'Alpha ships in March.', quote: 'March availability', ref: '[[Sources/Alpha (aaaaaaaa)|Alpha]]' }],
  gaps: [],
});

const textResponse = text => ({ role: 'assistant', content: [{ type: 'text', text }], stopReason: 'stop', usage: { input: 10, output: 5 } });

const toolResponse = (calls) => ({
  role: 'assistant',
  content: calls.map((call, index) => ({ type: 'toolCall', id: `call-${index}`, name: call.name, arguments: call.arguments })),
  stopReason: 'toolUse', usage: { input: 10, output: 5 },
});

function scriptedCaller(replies) {
  const seen = [];
  return {
    model: { id: 'm', provider: 'p', input: ['text'] },
    seen,
    async call(options) {
      seen.push(options);
      const next = replies.length > 1 ? replies.shift() : replies[0];
      if (next instanceof Error) throw next;
      return typeof next === 'function' ? next(options) : next;
    },
  };
}

const tools = () => {
  const executed = [];
  return {
    executed,
    list: [{
      name: 'web_search',
      description: 'search',
      parameters: { type: 'object', properties: {}, additionalProperties: false },
      async execute(callId, args) {
        executed.push({ callId, args });
        return { content: [{ type: 'text', text: '{"results":[]}' }], details: { results: [] } };
      },
    }],
  };
};

test('a worker feeds tool results back and returns the packet', async () => {
  const caller = scriptedCaller([
    toolResponse([{ name: 'web_search', arguments: { query: 'alpha' } }]),
    textResponse(PACKET),
  ]);
  const tool = tools();
  const packet = await runWorker({ caller, query: 'alpha', tools: tool.list });
  assert.equal(packet.findings.length, 1);
  assert.equal(packet.findings[0].ref, '[[Sources/Alpha (aaaaaaaa)|Alpha]]');
  assert.equal(packet.toolCalls, 1);
  const second = caller.seen[1].messages;
  const result = second.find(message => message.role === 'toolResult');
  assert.equal(result.toolCallId, 'call-0');
  assert.equal(result.toolName, 'web_search');
  assert.equal(result.isError, false);
  assert.equal(second[1].role, 'assistant');
});

test('a worker stops at the tool budget instead of looping', async () => {
  const caller = scriptedCaller([toolResponse([
    { name: 'web_search', arguments: {} }, { name: 'web_search', arguments: {} },
    { name: 'web_search', arguments: {} }, { name: 'web_search', arguments: {} },
  ])]);
  const tool = tools();
  const packet = await runWorker({ caller, query: 'alpha', tools: tool.list });
  assert.ok(packet.toolCalls <= MAX_TOOL_CALLS);
  assert.equal(tool.executed.length, packet.toolCalls);
  assert.match(packet.gaps.join(' '), /budget/i);
  assert.deepEqual(packet.findings, []);
});

test('a provider failure becomes a gap, not an exception', async () => {
  const caller = scriptedCaller([new Error('rate limit')]);
  const packet = await runWorker({ caller, query: 'alpha', tools: tools().list });
  assert.deepEqual(packet.findings, []);
  assert.match(packet.gaps[0], /rate limit/);
});

test('a malformed packet is retried once, then reported as a gap', async () => {
  const caller = scriptedCaller([textResponse('I found several sources but forgot the JSON.')]);
  const packet = await runWorker({ caller, query: 'alpha', tools: tools().list });
  assert.equal(caller.seen.length, 2);
  assert.match(packet.gaps.join(' '), /malformed/i);
  const stored = await runWorker({
    caller: scriptedCaller([textResponse('nonsense'), textResponse(PACKET)]),
    query: 'alpha', tools: tools().list,
  });
  assert.equal(stored.findings.length, 1);
});

test('runCrew isolates one failing worker from the rest', async () => {
  const caller = scriptedCaller([options => {
    const prompt = String(options.messages[0].content ?? '');
    if (prompt.includes('boom')) throw new Error('search provider blocked');
    return textResponse(PACKET);
  }]);
  const crew = await runCrew({ caller, queries: ['alpha', 'boom'], tools: tools().list });
  assert.equal(crew.packets.length, 2);
  const failed = crew.packets.find(packet => packet.query === 'boom');
  const ok = crew.packets.find(packet => packet.query === 'alpha');
  assert.match(failed.gaps.join(' '), /blocked/);
  assert.equal(ok.findings.length, 1);
});

