  const caller = scriptedCaller([toolResponse([
    { name: 'web_search', arguments: {} }, { name: 'web_search', arguments: {} },
    { name: 'web_search', arguments: {} }, { name: 'web_search', arguments: {} },
  ])]);
  const tool = tools();
  const packet = await runWorker({ caller, query: 'alpha', tools: tool.list });
  assert.ok(packet.toolCalls <= MAX_TOOL_CALLS);
  assert.equal(tool.executed.length, packet.toolCalls);
  assert.match(packet.gaps.join(' '), /budget/i);
  assert.deepEqual(packet.findings, []);
});

test('a provider failure becomes a gap, not an exception', async () => {
  const caller = scriptedCaller([new Error('rate limit')]);
  const packet = await runWorker({ caller, query: 'alpha', tools: tools().list });
  assert.deepEqual(packet.findings, []);
  assert.match(packet.gaps[0], /rate limit/);
});

test('a malformed packet is retried once, then reported as a gap', async () => {
