import { afterEach, beforeEach, test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdir, mkdtemp, readFile, rm, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { normalizeUrl, openVault } from '../src/vault.mjs';

let root;
let outside;

beforeEach(async () => {
  root = await mkdtemp(join(tmpdir(), 'discover-vault-'));
  outside = await mkdtemp(join(tmpdir(), 'discover-outside-'));
  await mkdir(join(root, '.obsidian'), { recursive: true });
});

afterEach(async () => {
  await rm(root, { recursive: true, force: true });
  await rm(outside, { recursive: true, force: true });
});

const isAlive = pid => { try { process.kill(pid, 0); return true; } catch (error) { return error.code === 'EPERM'; } };

function deadPid() {
  for (let pid = 900_000; pid > 800_000; pid--) if (!isAlive(pid)) return pid;
  throw new Error('No dead pid available for the lock test.');
}

const writeLock = (vault, lock) => writeFile(join(vault.root, '_discover', 'writer.lock'), `${JSON.stringify(lock)}\n`, 'utf8');

test('a vault that is missing, a file, or has no .obsidian is refused', async () => {
  await assert.rejects(openVault(join(root, 'absent')), /That vault folder does not exist\./);
  const file = join(outside, 'file.txt');
  await writeFile(file, 'x');
  await assert.rejects(openVault(file), /That vault folder does not exist\./);
  const bare = join(outside, 'bare');
  await mkdir(bare);
  await assert.rejects(openVault(bare), /must contain its own \.obsidian directory/);
});

test('the vault refuses to nest inside a Scholar vault and the reverse', async () => {
  await assert.rejects(openVault(root, { scholarRoots: [join(root, 'nested')] }), /must be separate, non-nested folders/);
  await assert.rejects(openVault(root, { scholarRoots: [dirname(root)] }), /must be separate, non-nested folders/);
});

test('paths cannot escape the vault', async () => {
  const vault = await openVault(root);
  await vault.ensure();
  await assert.rejects(vault.writeFile('../escape.md', 'x'), error => error.code === 'ERR_PATH_ESCAPE');
  await assert.rejects(vault.writeFile('/etc/passwd', 'x'), error => error.code === 'ERR_PATH_ESCAPE');
  await assert.rejects(vault.writeFile('C:/Windows/evil.md', 'x'), error => error.code === 'ERR_PATH_ESCAPE');
  await assert.rejects(vault.readFile('_discover/../..//..//secret'), error => error.code === 'ERR_PATH_ESCAPE');
});

test('a symlink inside the vault cannot be used to write outside it', async () => {
  const vault = await openVault(root);
  await vault.ensure();
  await symlink(outside, join(root, 'link'), 'junction');
  await assert.rejects(vault.writeFile('link/out.md', 'x'), error => error.code === 'ERR_PATH_ESCAPE');
});

test('ensure adopts the identity of a vault linked by the previous version', async () => {
  await mkdir(join(root, '_Research'), { recursive: true });
  await writeFile(join(root, '_Research', 'vault.json'), JSON.stringify({ version: 1, id: 'legacy-id', createdAt: 'then' }));
  const vault = await openVault(root, { expectedId: 'legacy-id' });
  await vault.ensure();
  assert.equal(vault.id, 'legacy-id');
  const written = JSON.parse(await readFile(join(root, '_discover', 'vault.json'), 'utf8'));
  assert.equal(written.id, 'legacy-id');
});

test('a different vault than the linked one is refused', async () => {
  const vault = await openVault(root, { expectedId: 'a-different-vault' });
  await assert.rejects(vault.ensure(), /identity does not match the saved binding/);
});

test('a lock from a dead process on this host is stolen', async () => {
  const vault = await openVault(root);
  await vault.ensure();
  await writeLock(vault, { version: 1, pid: deadPid(), host: (await import('node:os')).hostname(), startedAt: 'then', token: 'stale' });
  await vault.acquireLock();
  const lock = await vault.isLocked();
  assert.equal(lock.pid, process.pid);
  const released = await vault.releaseLock();
  assert.equal(released, true);
  assert.equal(await vault.isLocked(), null);
});

test('a lock from a live process is respected and only that owner can clear it', async () => {
  const vault = await openVault(root);
  await vault.ensure();
  const { hostname } = await import('node:os');
  assert.ok(isAlive(process.ppid));
  await writeLock(vault, { version: 1, pid: process.ppid, host: hostname(), startedAt: 'now', token: 'other' });
  await assert.rejects(vault.acquireLock(), /being written by/);
  await assert.rejects(vault.unlockStale(), /being written by/);
  assert.equal(await vault.releaseLock(), false, 'a lock this session does not own must survive release');
  assert.notEqual(await vault.isLocked(), null);
});

test('normalizeUrl drops tracking, fragments and default ports, and sorts the query', () => {
  assert.equal(
    normalizeUrl('https://Example.COM:443/a/?utm_source=x&b=2&a=1&fbclid=z#frag'),
    'https://example.com/a?a=1&b=2',
  );
  assert.equal(normalizeUrl('https://example.com'), 'https://example.com');
  assert.equal(normalizeUrl('http://example.com/'), 'http://example.com');
});

