import { afterEach, beforeEach, test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdir, mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DISCOVER_COMMANDS, discoverHelp, getDiscoverArgumentCompletions, parseCommand } from '../src/commands.mjs';
import { registerDiscover } from '../src/extension.mjs';

let configDir;

beforeEach(async () => {
  configDir = await mkdtemp(join(tmpdir(), 'discover-config-'));
  process.env.PI_RESEARCH_CONFIG_DIR = configDir;
});

afterEach(async () => {
  delete process.env.PI_RESEARCH_CONFIG_DIR;
  await rm(configDir, { recursive: true, force: true });
});

function fakeHost() {
  const host = {
    messages: [],
    handlers: {},
    registerCommand(name, definition) { host.command = { name, definition }; },
    on(event, handler) { host.handlers[event] = handler; },
    sendMessage(message) { host.messages.push(message); },
  };
  return host;
}

function fakeContext() {
  const context = {
    notices: [],
    isIdle: () => true,
    sessionManager: { getBranch: () => [] },
    model: { id: 'test-model', provider: 'test', input: ['text'] },
    thinkingLevel: 'off',
    modelRegistry: {},
    hasUI: true,
    ui: {
      notify: (message, level) => context.notices.push({ message, level }),
      setStatus() {}, setWidget() {}, getEditorText: () => '', setEditorText() {}, async select() { return null; },
    },
  };
  return context;
}

test('parseCommand keeps quoted arguments whole and drops the quotes', () => {
  assert.deepEqual(parseCommand('attach "C:\\Papers\\a study.pdf"'), { command: 'attach', argument: 'C:\\Papers\\a study.pdf' });
  assert.deepEqual(parseCommand('new'), { command: 'new', argument: '' });
  assert.deepEqual(parseCommand(''), { command: '', argument: '' });
  assert.deepEqual(parseCommand("vault 'D:\\Vault'"), { command: 'vault', argument: 'D:\\Vault' });
});

test('completions cover every command and help sub-topics', () => {
  const bare = getDiscoverArgumentCompletions('');
  assert.equal(bare.length, DISCOVER_COMMANDS.length);
  assert.deepEqual(getDiscoverArgumentCompletions('at').map(item => item.value), ['attach ']);
  assert.deepEqual(getDiscoverArgumentCompletions('help at').map(item => item.value), ['help attach']);
  assert.equal(getDiscoverArgumentCompletions('attach "C:/a'), null, 'paths are never rewritten');
});

test('help describes every command and rejects an unknown topic', () => {
  const guide = discoverHelp();
  for (const command of DISCOVER_COMMANDS) {
    const usage = command.name ? `/discover ${command.name}` : '/discover\n';
    assert.ok(guide.includes(usage), `help mentions ${command.name || 'the bare command'}`);
  }
  assert.ok(discoverHelp('attach').includes('/discover attach "file path"'));
  assert.throws(() => discoverHelp('fork'), /Unknown help topic/);
});

test('the catalogue keeps only the chat-era commands', () => {
  const names = DISCOVER_COMMANDS.map(item => item.name);
  assert.deepEqual(names, ['', 'attach', 'clear', 'exit', 'help', 'new', 'pick', 'stop', 'unlock', 'vault']);
  for (const gone of ['ask', 'deep', 'fork', 'branch', 'resume', 'install-plugin', 'repair', 'continue', 'clear-attachments']) {
    assert.ok(!names.includes(gone), `${gone} is gone`);
  }
});

test('the extension registers one command, an input hook and a shutdown hook', async () => {
  const pi = fakeHost();
  registerDiscover(pi);
  assert.equal(pi.command.name, 'discover');
  assert.equal(typeof pi.command.definition.getArgumentCompletions, 'function');
  assert.equal(typeof pi.handlers.input, 'function');
  assert.equal(typeof pi.handlers.session_start, 'function');
  assert.equal(typeof pi.handlers.session_shutdown, 'function');
});

test('with no linked vault the command explains how to link one', async () => {
  const pi = fakeHost();
  registerDiscover(pi);
  const ctx = fakeContext();
  await pi.command.definition.handler('', ctx);
  assert.equal(ctx.notices.length, 1);
  assert.equal(ctx.notices[0].level, 'error');
  assert.match(ctx.notices[0].message, /Link an existing vault first: \/discover vault/);
});

test('an unknown subcommand names the recovery step and help never throws', async () => {
  const pi = fakeHost();
  registerDiscover(pi);
  const ctx = fakeContext();
  await pi.command.definition.handler('frobnicate', ctx);
  assert.match(ctx.notices[0].message, /Unknown Discover command\. Use \/discover help\./);
  await pi.command.definition.handler('help', ctx);
  assert.match(ctx.notices.at(-1).message, /ask in Pi/);
  assert.equal(ctx.notices.at(-1).level, 'info');
});

test('input before /discover is left to Pi, and a busy Discover keeps the draft', async () => {
  const pi = fakeHost();
  registerDiscover(pi);
  const ctx = fakeContext();
  const event = { text: 'Why is the sky blue?', source: 'user' };
  assert.deepEqual(pi.handlers.input(event, ctx), { action: 'continue' }, 'no chat is open yet');
  const { handler } = pi.command.definition;
  await handler('help', ctx);
  assert.deepEqual(pi.handlers.input(event, ctx), { action: 'continue' }, 'help does not open a chat');
});

