    out.push(fence ? trimmed : trimmed
      .replace(/\\\(/g, () => '$').replace(/\\\)/g, () => '$')
      .replace(/\\\[/g, () => '$$').replace(/\\\]/g, () => '$$'));
  }
  const collapsed = [];
  let blanks = 0;
