import test from 'node:test';
import assert from 'node:assert/strict';
import {
  MARKERS, appendExchange, callout, chatNoteHeader, normalizeObsidianMarkdown,
  recentExchanges, relatedBlock, replaceHeader, rewriteBlock, sanitizeTitle,
  splitExchanges, uniquePath, sourceRef,
} from '../src/notes.mjs';

test('appendExchange leaves everything before the new section untouched', () => {
  const first = appendExchange('', { index: 1, question: 'First?', provenance: '> [!info]- one', body: 'Body one.' });
  const second = appendExchange(first, { index: 2, question: 'Second?', provenance: '> [!info]- two', body: 'Body two.' });
  const before = second.slice(0, second.indexOf('## 2.'));
  assert.equal(before, `${first}\n\n`);
  assert.equal(second.match(/## 1\. First\?/g).length, 1);
});

test('appendExchange inserts above the related block', () => {
  const related = relatedBlock([{ path: 'Chats/2026-01-01 Other', reason: 'shares [[Sources/X]]' }]);
  const note = `# Title\n\n## 1. Old?\n\nold body\n\n${related}\n`;
  const next = appendExchange(note, { index: 2, question: 'New?', provenance: '', body: 'new body' });
  assert.ok(next.indexOf('## 2. New?') < next.indexOf(MARKERS.related.start));
  assert.ok(next.trimEnd().endsWith(MARKERS.related.end));
});

test('rewriteBlock is idempotent and appends when the markers are gone', () => {
  const note = `# T\n\ntext\n\n${MARKERS.related.start}\nold\n${MARKERS.related.end}\n`;
  const block = relatedBlock([{ path: 'Chats/2026-01-02 B', reason: 'shares 3 topics' }]);
  const once = rewriteBlock(note, 'related', block);
  assert.equal(rewriteBlock(once, 'related', block), once);
  const orphan = rewriteBlock('# T\n\ntext\n', 'related', block);
  assert.ok(orphan.includes(MARKERS.related.start));
  assert.equal(rewriteBlock(orphan, 'related', '').includes(MARKERS.related.start), false);
});

test('splitExchanges round-trips a two-exchange note', () => {
  const note = `${chatNoteHeader({ id: 'c1', title: 'T', createdAt: 'now', updatedAt: 'now', topics: [], model: 'p/m' })}`
    + `\n## 1. First question?\n\n> [!info]- asked\n\nFirst body.\n\n## 2. Second question?\n\nSecond body.\n`;
  const exchanges = splitExchanges(note);
  assert.equal(exchanges.length, 2);
  assert.equal(exchanges[0].question, 'First question?');
  assert.ok(exchanges[0].body.includes('First body.'));
  assert.ok(!exchanges[0].body.includes('Second body.'));
  assert.equal(exchanges[1].question, 'Second question?');
});

test('splitExchanges ignores headings inside fenced code', () => {
  const note = '## 1. Q?\n\n```mermaid\n## not a heading\n```\n\ntail\n';
  const exchanges = splitExchanges(note);
  assert.equal(exchanges.length, 1);
  assert.ok(exchanges[0].body.includes('## not a heading'));
});

test('recentExchanges keeps the last exchanges within the character budget', () => {
  const parts = [];
  for (let index = 1; index <= 4; index++) parts.push({ index, question: `Q${index}?`, provenance: '', body: `A${index}` });
  const note = parts.reduce((text, part) => appendExchange(text, part), '');
  const recent = recentExchanges(note, 2, 6000);
  assert.ok(recent.includes('Q3?') && recent.includes('Q4?'));
  assert.ok(!recent.includes('Q2?'));
  const tight = recentExchanges(note, 3, 12);
  assert.ok(tight.length <= 12);
});

test('normalizeObsidianMarkdown converts delimiters but not inside fenced code', () => {
  const text = 'Inline \\(x^2\\) and display \\[y\\].\n\n```tex\n\\(keep\\]\n```\n';
  const normalized = normalizeObsidianMarkdown(text);
  assert.ok(normalized.includes('Inline $x^2$ and display $$y$$.'));
  assert.ok(normalized.includes('\\(keep\\]'));
  assert.ok(normalized.endsWith('\n'));
});

test('normalizeObsidianMarkdown collapses long blank runs', () => {
  const normalized = normalizeObsidianMarkdown('a\n\n\n\n\nb\n');
  assert.equal(normalized, 'a\n\n\nb\n');
});

test('sanitizeTitle strips forbidden characters and caps length', () => {
  assert.equal(sanitizeTitle('Why: is this/that? #1'), 'Why is this that 1');
  assert.equal(sanitizeTitle('   '), 'Untitled chat');
  assert.equal(sanitizeTitle('x'.repeat(120)).length, 80);
  assert.equal(sanitizeTitle('Trailing dots...'), 'Trailing dots');
});

test('sanitizeTitle output cannot break a wiki-link or a filename', () => {
  const name = sanitizeTitle('A|B[[C]]^D#E');
  assert.ok(!/[|[\]^#]/.test(name));
  const ref = sourceRef('abc12345', 'A|B', 'abc12345');
  assert.equal(ref, '[[Sources/A B (abc12345)|A B]]');
  assert.ok(!ref.includes('\n'));
});

test('uniquePath appends a counter on collision', async () => {
  const taken = new Set(['Chats/2026-01-01 T.md', 'Chats/2026-01-01 T 2.md']);
  const path = await uniquePath(candidate => taken.has(candidate), 'Chats', '2026-01-01 T', '.md');
  assert.equal(path, 'Chats/2026-01-01 T 3.md');
});

test('callout keeps one quoted line per body line and marks blank lines', () => {
  const block = callout('warning', 'Careful', 'first\n\nsecond', { collapsed: true });
  assert.deepEqual(block.split('\n'), ['> [!warning]- Careful', '> first', '>', '> second']);
});

test('replaceHeader swaps frontmatter and H1 without touching the body', () => {
  const note = '---\ntitle: old\n---\n\n# Old\n\nbody text\n';
  const next = replaceHeader(note, chatNoteHeader({ id: 'c1', title: 'New', createdAt: 'a', updatedAt: 'b', topics: ['x'], model: 'p/m' }, { sourceCount: 2 }));
  assert.ok(next.startsWith('---\n'));
  assert.ok(next.includes('title: "New"'));
  assert.ok(next.includes('# New'));
  assert.ok(next.trimEnd().endsWith('body text'));
});

