    return (entries || []).map(entry => ({ name: entry.name, isDirectory: entry.isDirectory() }));
  }

  async isLocked() {
    const lock = await this.readJson(LOCK_PATH).catch(() => null);
    return lock && typeof lock === 'object' ? lock : null;
  }

  /** A same-host, dead-pid lock is stolen; anything else refuses the turn. */
  async acquireLock() {
    const busy = lock => {
      throw new Error(`This vault is being written by ${lock?.host || 'another Pi instance'}. Close that Pi instance or run /discover unlock.`);
    };
    const token = randomUUID();
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const handle = await fs.open(await this.safePath(LOCK_PATH), 'wx');
        try {
          await handle.writeFile(jsonText({ version: 1, pid: process.pid, host: os.hostname(), startedAt: now(), token }));
          await handle.sync();
        } finally { await handle.close(); }
        this.lockToken = token;
        return token;
      } catch (error) {
        if (error.code !== 'EEXIST') throw error;
        const current = await this.isLocked();
        if (current?.host === os.hostname() && current.pid === process.pid) {
          this.lockToken = current.token;
          return current.token;
        }
        if (current?.host === os.hostname() && Number.isInteger(current.pid) && !alive(current.pid)) {
          await fs.unlink(await this.safePath(LOCK_PATH)).catch(() => {});
          continue;
        }
        busy(current);
      }
    }
    busy(await this.isLocked());
  }

  async releaseLock() {
    if (!this.lockToken) return false;
    const current = await this.isLocked();
    if (current?.token !== this.lockToken) { this.lockToken = null; return false; }
    await fs.unlink(await this.safePath(LOCK_PATH)).catch(error => { if (error.code !== 'ENOENT') throw error; });
    this.lockToken = null;
    return true;
  }

  async unlockStale() {
    const current = await this.isLocked();
    if (!current) return false;
    if (current.host === os.hostname() && Number.isInteger(current.pid) && !alive(current.pid)) {
      await fs.unlink(await this.safePath(LOCK_PATH));
      return true;
    }
    throw new Error(`This vault is being written by ${current.host || 'another Pi instance'}. Close that Pi instance or run /discover unlock.`);
  }

  /**
   * Write (or refresh) one source note. Identity is the normalized URL for web
   * pages and the content hash for files, so the same source is never stored twice.
   * On reuse the recorded file and title win, which keeps the wiki-link the writer
   * was given pointing at a file that exists.
   */
  async storeSource({ url, title, kind = 'web', text, hash: contentHash }) {
    const body = String(text ?? '').trim();
    if (!body) throw new Error('A source needs extracted text.');
    if (!['web', 'pdf'].includes(kind)) throw new Error('A source kind must be web or pdf.');
    const id = kind === 'pdf' ? String(contentHash || '') : hash(normalizeUrl(url));
    if (!HASH.test(id)) throw new Error('A PDF source needs the sha256 of its bytes.');
    const recorded = await this.index.getSource(id);
    const name = sanitizeTitle(recorded?.title || title || (kind === 'web' ? new URL(url).hostname : 'Document'));
    const relative = recorded?.path || await this.sourcePath(name, id);
    const previous = await this.readFile(relative).catch(() => null);
    const references = previous ? referenceTargets(previous) : [];
    const note = `${frontmatter({
      discover: 'source', title: name, url: kind === 'web' ? url : undefined,
      kind, retrieved: now(), hash: id,
    })}# ${name}\n\n${normalizeObsidianMarkdown(body).trim()}\n\n${refsBlock(references)}\n`;
    await this.writeFile(relative, note);
    await this.index.upsertSource({ id, path: relative, url: kind === 'web' ? url : '', title: name, kind, retrievedAt: now() });
    return { id, path: relative, ref: sourceLink(relative, name), title: name, reused: Boolean(recorded) };
  }

  /** The first free `Sources/<name> (<hash prefix>).md`; a longer prefix breaks a tie. */
  async sourcePath(name, id) {
    for (const width of [8, 12, 16, 24, 48, 64]) {
      const candidate = `${SOURCE_DIR}/${sourceFileName(name, id.slice(0, width))}`;
      if (!(await this.exists(candidate))) return candidate;
    }
    throw new Error(`Too many sources named ${name} in this vault.`);
  }

  async findSourceByUrl(url) { return this.index.findSourceByUrl(url); }

  /** The stored, extracted text of a source, without note scaffolding. */
  async readSourceText(id) {
    const record = await this.index.getSource(id);
    if (!record) return null;
    const raw = await this.readFile(record.path).catch(() => null);
    if (raw === null) return null;
    const { data, body } = parseFrontmatter(raw);
    const text = body
      .replace(/^#\s+.*$/m, '')
      .split(MARKERS.refs.start)[0]
      .trim();
    return {
      title: typeof data.title === 'string' ? data.title : record.title,
      url: typeof data.url === 'string' ? data.url : '', kind: record.kind,
      path: record.path, text: text.slice(0, MAX_SOURCE_TEXT), truncated: text.length > MAX_SOURCE_TEXT,
    };
  }

  async noteSourceReference(sourceId, chatPath) {
    const record = await this.index.getSource(sourceId);
    if (!record) return false;
    const note = await this.readFile(record.path).catch(() => null);
    if (note === null) return false;
    const targets = referenceTargets(note);
    const target = String(chatPath).replace(/\.md$/, '');
    if (!targets.includes(target)) targets.push(target);
    await this.writeFile(record.path, rewriteBlock(note, 'refs', refsBlock(targets)));
    return true;
  }

  async writeChatNote(record, text) { return this.writeFile(record.notePath, text); }
  async readChatNote(record) {
    const text = await this.readFile(record.notePath).catch(() => null);
    return text;
  }

  /** Recover a chat whose note was moved or renamed by the user. */
  async findChatNote(chatId) {
    for (const entry of await this.listDir(CHAT_DIR)) {
      if (entry.isDirectory || !entry.name.endsWith('.md')) continue;
      const relative = `${CHAT_DIR}/${entry.name}`;
      const text = await this.readFile(relative).catch(() => null);
      if (text === null) continue;
      if (parseFrontmatter(text).data.chat === chatId) return relative;
    }
    return null;
  }

  async relatedChats(chatId, { limit = 3 } = {}) { return this.index.related(chatId, limit); }

  async getChat(id) { return this.index.getChat(id); }

  async getChatRecord(id) { return this.index.getChatRecord(id); }

  async getSource(id) { return this.index.getSource(id); }

  /** Newest first, with records whose note file disappeared dropped and reported. */
  async listChats() {
    const chats = await this.index.chats();
    const present = [];
    this.skippedChats = [];
    for (const chat of chats) {
      if (await this.exists(chat.path)) present.push(chat);
      else this.skippedChats.push(chat.title || chat.path);
    }
    return present;
  }

  async saveChat(record) { await this.index.saveChat(record); }

  async setActive(chatId) { await this.index.setActive(chatId); }

  async getActive() { return this.index.getActive(); }
}

function referenceTargets(noteText) {
  const region = String(noteText).split(MARKERS.refs.start)[1]?.split(MARKERS.refs.end)[0] || '';
  return [...region.matchAll(/^- \[\[([^\]|]+)(?:\|[^\]]*)?\]\]$/gm)].map(match => match[1].trim());
}

export async function openVault(input, { scholarRoots = [], expectedId } = {}) {
  const root = await vaultRoot(input);
  for (const scholar of scholarRoots.filter(Boolean)) {
    const other = await potentialRealPath(scholar);
    if (within(root, other) || within(other, root)) throw new Error('Discover and Scholar vaults must be separate, non-nested folders');
  }
  return new Vault(root, { expectedId });
}

export { vaultRoot, relativePath };

