  assert.ok(exchanges[0].body.includes('## not a heading'));
});

test('recentExchanges keeps the last exchanges within the character budget', () => {
  const parts = [];
  for (let index = 1; index <= 4; index++) parts.push({ index, question: `Q${index}?`, provenance: '', body: `A${index}` });
  const note = parts.reduce((text, part) => appendExchange(text, part), '');
  const recent = recentExchanges(note, 2, 6000);
  assert.ok(recent.includes('Q3?') && recent.includes('Q4?'));
  assert.ok(!recent.includes('Q2?'));
  const tight = recentExchanges(note, 3, 12);
  assert.ok(tight.length <= 12);
});

test('normalizeObsidianMarkdown converts delimiters but not inside fenced code', () => {
  const text = 'Inline \\(x^2\\) and display \\[y\\].\n\n```tex\n\\(keep\\]\n```\n';
  const normalized = normalizeObsidianMarkdown(text);
  assert.ok(normalized.includes('Inline $x^2$ and display $$y$$.'));
  assert.ok(normalized.includes('\\(keep\\]'));
  assert.ok(normalized.endsWith('\n'));
});

test('normalizeObsidianMarkdown collapses long blank runs', () => {
  const normalized = normalizeObsidianMarkdown('a\n\n\n\n\nb\n');
  assert.equal(normalized, 'a\n\n\nb\n');
});

test('sanitizeTitle strips forbidden characters and caps length', () => {
  assert.equal(sanitizeTitle('Why: is this/that? #1'), 'Why is this that 1');
  assert.equal(sanitizeTitle('   '), 'Untitled chat');
  assert.equal(sanitizeTitle('x'.repeat(120)).length, 80);
  assert.equal(sanitizeTitle('Trailing dots...'), 'Trailing dots');
});

test('sanitizeTitle output cannot break a wiki-link or a filename', () => {
  const name = sanitizeTitle('A|B[[C]]^D#E');
  assert.ok(!/[|[\]^#]/.test(name));
  assert.equal(sourceFileName('A|B', 'abc12345'), 'A B (abc12345).md');
  assert.ok(!sourceFileName('A|B', 'abc12345').includes('\n'));
});

test('uniquePath appends a counter on collision', async () => {
  const taken = new Set(['Chats/2026-01-01 T.md', 'Chats/2026-01-01 T 2.md']);
  const path = await uniquePath(candidate => taken.has(candidate), 'Chats', '2026-01-01 T', '.md');
  assert.equal(path, 'Chats/2026-01-01 T 3.md');
});

test('callout keeps one quoted line per body line and marks blank lines', () => {
  const block = callout('warning', 'Careful', 'first\n\nsecond', { collapsed: true });
  assert.deepEqual(block.split('\n'), ['> [!warning]- Careful', '> first', '>', '> second']);
});

test('replaceHeader swaps frontmatter and H1 without touching the body', () => {
  const note = '---\ntitle: old\n---\n\n# Old\n\nbody text\n';
  const next = replaceHeader(note, chatNoteHeader({ id: 'c1', title: 'New', createdAt: 'a', updatedAt: 'b', topics: ['x'], model: 'p/m' }, { sourceCount: 2 }));
  assert.ok(next.startsWith('---\n'));
  assert.ok(next.includes('title: "New"'));
  assert.ok(next.includes('# New'));
  assert.ok(next.trimEnd().endsWith('body text'));
});

