import { afterEach, beforeEach, test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { openVault } from '../src/vault.mjs';

let root;
let vault;

beforeEach(async () => {
  root = await mkdtemp(join(tmpdir(), 'discover-index-'));
  await mkdir(join(root, '.obsidian'), { recursive: true });
  vault = await openVault(root);
  await vault.ensure();
});

afterEach(async () => { await rm(root, { recursive: true, force: true }); });

const HASH = 'a'.repeat(64);
const sourceFiles = async () => (await vault.listDir('Sources')).filter(entry => entry.name.endsWith('.md')).map(entry => entry.name);

test('the same page fetched twice is stored once, whatever its tracking parameters', async () => {
  const first = await vault.storeSource({ url: 'https://example.com/alpha?utm_source=newsletter', title: 'Alpha', kind: 'web', text: 'Alpha text.' });
  const second = await vault.storeSource({ url: 'https://example.com/alpha?utm_medium=email#section', title: 'Alpha page', kind: 'web', text: 'Alpha text.' });
  assert.equal(second.id, first.id);
  assert.equal(second.reused, true);
  assert.equal(second.path, first.path);
  assert.equal(second.ref, '[[Sources/Alpha (aaaaaaaa)|Alpha]]');
  assert.deepEqual(await sourceFiles(), ['Alpha (aaaaaaaa).md']);
  assert.equal(await vault.findSourceByUrl('https://example.com/alpha'), first.id);
});

test('a refreshed page rewrites the stored text without losing its references', async () => {
  const stored = await vault.storeSource({ url: 'https://example.com/alpha', title: 'Alpha', kind: 'web', text: 'Old text.' });
  await vault.noteSourceReference(stored.id, 'Chats/2026-01-01 Alpha questions.md');
  const refreshed = await vault.storeSource({ url: 'https://example.com/alpha', title: 'Alpha', kind: 'web', text: 'New text.' });
  assert.equal(refreshed.path, stored.path);
  const note = await vault.readFile(refreshed.path);
  assert.ok(note.includes('New text.'));
  assert.ok(!note.includes('Old text.'));
  assert.ok(note.includes('- [[Chats/2026-01-01 Alpha questions]]'), 'the reference survives a refresh');
  const read = await vault.readSourceText(refreshed.id);
  assert.equal(read.text, 'New text.');
});

test('two sources with the same title do not overwrite each other', async () => {
  const first = await vault.storeSource({ url: 'https://example.com/one', title: 'Report', kind: 'web', text: 'One.' });
  const second = await vault.storeSource({ url: 'https://other.example/two', title: 'Report', kind: 'web', text: 'Two.' });
  assert.notEqual(first.path, second.path);
  const names = await sourceFiles();
  assert.equal(names.length, 2);
  assert.ok(names.every(name => name.startsWith('Report (') && name.endsWith(').md')));
  assert.equal((await vault.readSourceText(first.id)).text, 'One.');
  assert.equal((await vault.readSourceText(second.id)).text, 'Two.');
});

test('a PDF is identified by its content hash', async () => {
  const first = await vault.storeSource({ url: 'C:/papers/study.pdf', title: 'Study', kind: 'pdf', hash: HASH, text: '## Page 1\n\nBody.' });
  const second = await vault.storeSource({ url: 'D:/elsewhere/renamed.pdf', title: 'Study', kind: 'pdf', hash: HASH, text: '## Page 1\n\nBody.' });
  assert.equal(second.id, HASH);
  assert.equal(second.reused, true);
  assert.equal((await sourceFiles()).length, 1);
  const note = await vault.readFile(first.path);
  assert.ok(note.includes('kind: "pdf"'));
  assert.ok(note.includes('hash:'));
  await assert.rejects(vault.storeSource({ url: 'x.pdf', title: 'Broken', kind: 'pdf', text: 'body' }), /sha256/);
});

test('a corrupt index is rebuilt from the notes instead of failing the turn', async () => {
  const stored = await vault.storeSource({ url: 'https://example.com/alpha', title: 'Alpha', kind: 'web', text: 'Alpha text.' });
  await writeFile(join(root, '_discover', 'index.json'), '{ half a file', 'utf8');
  const found = await vault.findSourceByUrl('https://example.com/alpha');
  assert.equal(found, stored.id);
  const rebuilt = JSON.parse(await readFile(join(root, '_discover', 'index.json'), 'utf8'));
  assert.equal(rebuilt.sources[stored.id].path, stored.path);
  assert.equal(rebuilt.sources[stored.id].title, 'Alpha');
});

test('chats survive a restart through their record files', async () => {
  const at = new Date().toISOString();
  await vault.saveChat({ id: 'chat-1', title: 'Alpha questions', notePath: 'Chats/2026-01-01 Alpha questions.md', createdAt: at, updatedAt: at, model: 'p/m', topics: ['alpha'], sources: [], turns: 1 });
  await vault.writeChatNote({ notePath: 'Chats/2026-01-01 Alpha questions.md' }, '# Alpha questions\n');
  const reopened = await openVault(root);
  await reopened.ensure();
  const record = await reopened.getChatRecord('chat-1');
  assert.equal(record.title, 'Alpha questions');
  assert.equal(record.turns, 1);
  const listed = await reopened.listChats();
  assert.deepEqual(listed.map(chat => chat.id), ['chat-1']);
});

test('a chat whose note file is gone is dropped and reported', async () => {
  const at = new Date().toISOString();
  await vault.saveChat({ id: 'chat-2', title: 'Orphan', notePath: 'Chats/2026-01-01 Orphan.md', createdAt: at, updatedAt: at, model: 'p/m', topics: [], sources: [], turns: 1 });
  const listed = await vault.listChats();
  assert.deepEqual(listed, []);
  assert.deepEqual(vault.skippedChats, ['Orphan']);
});

test('related chats need two shared sources or three shared topics', async () => {
  const at = new Date().toISOString();
  const base = { createdAt: at, updatedAt: at, model: 'p/m', turns: 1 };
  await vault.saveChat({ ...base, id: 'me', title: 'Mine', notePath: 'Chats/2026-01-01 Mine.md', topics: ['alpha', 'beta', 'gamma'], sources: ['s1', 's2', 's3'] });
  await vault.saveChat({ ...base, id: 'close', title: 'Close', notePath: 'Chats/2026-01-02 Close.md', topics: [], sources: ['s1', 's2'] });
  await vault.saveChat({ ...base, id: 'topics', title: 'Topics', notePath: 'Chats/2026-01-03 Topics.md', topics: ['alpha', 'beta', 'gamma'], sources: [] });
  await vault.saveChat({ ...base, id: 'far', title: 'Far', notePath: 'Chats/2026-01-04 Far.md', topics: ['alpha'], sources: ['s1'] });
  const related = await vault.relatedChats('me', { limit: 3 });
  assert.deepEqual(related.map(entry => entry.id).sort(), ['close', 'topics']);
  assert.match(related.find(entry => entry.id === 'topics').reason, /3 topics/);
});

test('reopening the active chat works without a vault scan', async () => {
  const at = new Date().toISOString();
  await vault.saveChat({ id: 'chat-3', title: 'Active', notePath: 'Chats/2026-01-01 Active.md', createdAt: at, updatedAt: at, model: 'p/m', topics: [], sources: [], turns: 2 });
  await vault.setActive('chat-3');
  const reopened = await openVault(root);
  await reopened.ensure();
  assert.equal(await reopened.getActive(), 'chat-3');
  assert.equal((await reopened.getChatRecord('chat-3')).turns, 2);
});

