import test from 'node:test';
import assert from 'node:assert/strict';
import { parseOutcome, writeAnswer, writerContext } from '../src/answer.mjs';

const GOOD = [
  '<<<META>>>',
  '{"title": "Alpha availability", "topics": ["systems", "gpu"], "confidence": "high", "open": []}',
  '<<<BRIEF>>>',
  'Alpha ships in March. Supply is the constraint, not demand.',
  '<<<NOTE>>>',
  'Alpha ships in March, limited by packaging capacity.',
].join('\n');

const response = text => ({
  role: 'assistant', content: [{ type: 'text', text }], stopReason: 'stop',
  usage: { input: 100, output: 20, cacheRead: 0, cacheWrite: 0 },
});

function stubCaller(replies) {
  const calls = [];
  return {
    model: { id: 'test-model', provider: 'test', input: ['text'] },
    calls,
    async call(options) {
      calls.push(options.messages);
      const next = replies.length > 1 ? replies.shift() : replies[0];
      if (next instanceof Error) throw next;
      return response(next);
    },
  };
}

test('parseOutcome accepts a well-formed triple', () => {
  const { outcome, error } = parseOutcome(GOOD);
  assert.equal(error, undefined);
  assert.equal(outcome.meta.title, 'Alpha availability');
  assert.deepEqual(outcome.meta.topics, ['systems', 'gpu']);
  assert.equal(outcome.meta.confidence, 'high');
  assert.ok(outcome.brief.startsWith('Alpha ships in March.'));
  assert.ok(outcome.note.startsWith('Alpha ships in March, limited'));
});

test('parseOutcome rejects a missing note section, bad confidence and non-JSON metadata', () => {
  assert.match(parseOutcome('<<<META>>>\n{}\n<<<BRIEF>>>\nbrief').error, /three required sections/);
  assert.match(parseOutcome(GOOD.replace('"confidence": "high"', '"confidence": "certain"')).error, /confidence/);
  assert.match(parseOutcome(GOOD.replace('{"title"', '{title')).error, /metadata was not valid JSON|three required sections/);
  assert.match(parseOutcome(GOOD.replace('"systems", "gpu"', '"Systems"')).error, /kebab-case/);
  assert.match(parseOutcome(GOOD.replace('Alpha ships in March, limited by packaging capacity.', '')).error, /no note body/);
  assert.match(parseOutcome(GOOD.replace('Alpha ships in March. Supply', '')).error, /three required sections|no brief/);
});

test('writerContext carries every section and omits the empty ones', () => {
  const context = writerContext({
    question: 'Why is Alpha late?',
    recent: 'Q: earlier\nA: earlier answer',
    packets: [{ query: 'q', findings: [{ claim: 'c', ref: '[[Sources/A (aaaaaaaa)|A]]' }] }],
    attachmentText: 'page text',
    voice: 'Prefer short sentences.',
  });
  assert.ok(context.userContent.includes('## Question\nWhy is Alpha late?'));
  assert.ok(context.userContent.includes('## Conversation so far'));
  assert.ok(context.userContent.includes('[[Sources/A (aaaaaaaa)|A]]'));
  assert.ok(context.userContent.includes('## Attachments\npage text'));
  assert.ok(context.userContent.includes('## User writing preferences'));
  const bare = writerContext({ question: 'Q?' });
  assert.equal(bare.userContent, '## Question\nQ?');
  assert.ok(bare.systemPrompt.includes('<<<NOTE>>>'));
});

test('a well-formed answer is used as-is with a single call', async () => {
  const caller = stubCaller([GOOD]);
  const result = await writeAnswer({ caller, question: 'Why is Alpha late?' });
  assert.equal(caller.calls.length, 1);
  assert.equal(result.repaired, false);
  assert.equal(result.warning, '');
  assert.equal(result.outcome.meta.title, 'Alpha availability');
  assert.ok(result.tokens > 0);
});

test('a malformed answer is repaired exactly once', async () => {
  const caller = stubCaller(['I think Alpha is late because of packaging.', GOOD]);
  const result = await writeAnswer({ caller, question: 'Why is Alpha late?' });
  assert.equal(caller.calls.length, 2);
  assert.equal(result.repaired, true);
  assert.equal(result.warning, '');
  assert.equal(result.outcome.meta.title, 'Alpha availability');
  assert.ok(String(caller.calls[1].at(-1).content).includes('Return the three sections again'));
});

test('a twice-malformed answer still yields a usable note and a warning', async () => {
  const caller = stubCaller(['Alpha is late. Packaging is the bottleneck.']);
  const result = await writeAnswer({ caller, question: 'Why is Alpha late?' });
  assert.equal(caller.calls.length, 2);
  assert.equal(result.repaired, true);
  assert.match(result.warning, /malformed/);
  assert.equal(result.outcome.brief, 'Alpha is late. Packaging is the bottleneck.');
  assert.ok(result.outcome.note.includes('Packaging is the bottleneck'));
  assert.equal(result.outcome.meta.confidence, 'low');
  assert.equal(result.outcome.meta.title, 'Why is Alpha late');
});

