    { name: 'DuckDuckGo HTML', url: `https://html.duckduckgo.com/html/?q=${encoded}`, parse: searchResults },
    { name: 'Bing RSS', url: `https://www.bing.com/search?format=rss&q=${encoded}`, parse: rssResults },
  ];
